// 30.10: DeepSeek queues requests when busy (no rate limit, just slow). Reading a
// request normally takes 5-11 s, so: first try 15 s; on a timeout (or 429/5xx)
// one more try with 20 s -- a fresh request often gets through faster.
const EXTRACT_TIMEOUT_MS = Number(process.env.EXTRACT_TIMEOUT_MS || 15000);
const EXTRACT_RETRY_TIMEOUT_MS = Number(process.env.EXTRACT_RETRY_TIMEOUT_MS || 20000);
const retryableLlmError = err => !err.status ? /abort|timeout|fetch failed|ECONNRESET|socket/i.test(`${err.name} ${err.message}`) : (err.status === 429 || err.status >= 500);

// ─── LAST GOOD EXTRACTION PER CONVERSATION (30.10) ──────────────────────────
// DeepSeek slows down under heavy traffic instead of refusing (live 30.10,
// 11:26-11:31 MSK: request reading timed out 5×). Then the customer's click on a
// wizard button ("X6 40iX") came back as VEHICLE {} and the car was lost. Now each
// good extraction is remembered by the conversation it was made for; when reading
// fails, the previous message's extraction is reused. Nothing is lost: the model
// path reads every customer message itself (lookupLaximo customerText), so the
// clicked button still counts. A VIN typed in the new message is picked up too.
// Key: the last 8 messages the widget sent. For the next request, the same 8 are
// messages.slice(0, -2).slice(-8) (its previous messages minus our reply and the
// new customer message). In-memory, 2 h, max 1000 conversations.
const crypto = require('crypto');
const lastExtraction = new Map();
const LAST_EXTRACTION_TTL_MS = 2 * 60 * 60 * 1000;
const convoKey = msgs => crypto.createHash('sha1').update(JSON.stringify((msgs || []).slice(-8).map(m => [m.role, m.content]))).digest('hex');
function rememberExtraction(messages, extracted) {
  if (!extracted || !Object.keys(extracted).length) return;
  lastExtraction.set(convoKey(messages), { at: Date.now(), data: extracted });
  if (lastExtraction.size > 1000) lastExtraction.delete(lastExtraction.keys().next().value);
}
function previousExtraction(messages) {
  if (!Array.isArray(messages) || messages.length < 3) return null;
  const hit = lastExtraction.get(convoKey(messages.slice(0, -2)));
  if (!hit || Date.now() - hit.at > LAST_EXTRACTION_TTL_MS) return null;
  const out = JSON.parse(JSON.stringify(hit.data));
  const last = [...messages].reverse().find(m => m.role === 'user');
  const vin = last && typeof last.content === 'string' && last.content.toUpperCase().match(/\b[A-HJ-NPR-Z0-9]{17}\b/);
  if (vin) out.vin = vin[0];
  // Order status / contact questions belong to the old message, not this one.
  out.orderStatusQuestion = false;
  return out;
}

/** Adds a «снят с производства» line to every card whose number the catalog notes call discontinued. */
function markDiscontinuedCards(text, catalogParts) {
  const disc = new Set();
  for (const p of catalogParts || []) {
    if (!p || !p.oem) continue;
    if (Object.entries(p.notes || {}).some(([k, v]) => /не производ|снят с произв|end.of.production/i.test(`${k} ${v}`))) disc.add(laximo.normalizeOem(p.oem));
  }
  if (!disc.size) return text;
  const re = /<<<PRODUCTS>>>([\s\S]*?)<<<END_PRODUCTS>>>/;
  const m = String(text || '').match(re);
  if (!m) return text;
  let cards;
  try { cards = JSON.parse(m[1]); } catch { return text; }
  if (!Array.isArray(cards)) return text;
  let marked = 0;
  for (const c of cards) {
    if (c && c.article && disc.has(laximo.normalizeOem(c.article)) && !/снят с производства/i.test(c.best_for || '')) {
      c.best_for = `⚠ Снят с производства по каталогу BMW — менеджер подберёт актуальную замену.${c.best_for ? ' ' + c.best_for : ''}`;
      marked++;
    }
  }
  if (marked) console.log(`[chat] ${marked} card(s) marked discontinued`);
  return marked ? text.replace(re, `<<<PRODUCTS>>>\n${JSON.stringify(cards)}\n<<<END_PRODUCTS>>>`) : text;
}

// Tyres, rims, complete wheels (owner 04.11): the diagram is one picture of the
// part itself, so the card shows it WHOLE instead of zooming in on position 1.
const WHOLE_DIAGRAM_RE = /шин|покрышк|колес|колёс|кол\.\s*с|л\/с\s*диск|диск[иа]?\s+колес|lm\s*rad|\brad\b|tyre|tire|wheel/i;
const wholeDiagram = p => WHOLE_DIAGRAM_RE.test(`${p.unit || ''} ${p.name || ''}`) && !/тормоз|подшипник|ступиц|датчик|болт|гайк|колпач|грузик|рычаг|кожух|арк/i.test(`${p.unit || ''} ${p.name || ''}`);

/** A Laximo part without a price-list card -> product card with its diagram (see DIAGRAM CARDS). */
function diagramCardFor(p, live, carLabel) {
  const oem = laximo.normalizeOem(p.oem);
  const c = live && live.cheapest;
  const position = p.position || (p.code ? String(p.code).replace(/^\D+/, '') : null);
  const ref = p.schema && p.schema.vid ? diagramToken.sign({ oem, catalog: p.schema.catalog, vid: p.schema.vid, ssd: p.schema.ssd, unit: p.schema.unit }) : null;
  return {
    article: oem,
    name: p.name || 'Деталь BMW',
    brand: 'BMW',
    category: 'оригинальный каталог',
    compatibility: `${carLabel}${p.axle ? ' — ' + p.axle : ''}`,
    price: c && Number(c.price) > 0 ? Number(c.price) : 0,
    priceFrom: !!(c && Number(c.price) > 0),
    inStock: !!(c && (c.inStock || Number(c.days) === 0)),
    days: c && Number(c.days) > 0 ? Number(c.days) : null,
    offers: live ? live.count || null : null,
    slowDelivery: !!(live && live.slowOnly), // offers exist, none within ABCP_MAX_DELIVERY_DAYS
    stock: 0,
    url: null, // the widget opens the site search for the number
    picture: null,
    best_for: '',
    diagram: p.unitImage || ref ? { image: p.unitImage || null, position, unit: p.unit || null, ...(wholeDiagram(p) ? { whole: true } : {}), ...(ref ? { ref } : {}) } : null, // no diagram (pad paste) -> plain card
  };
}

/**
 * Several cards with the same name (M5 G90 live 05.11: two «Сменный элемент
 * фильтра», cylinders 1–4 and 5–8) -> each card's line shows its catalog note,
 * so the customer sees they are different parts. Pure.
 */
function labelSameNameCards(parts, cards) {
  const count = {};
  cards.forEach(c => { count[c.name] = (count[c.name] || 0) + 1; });
  return cards.map((c, i) => {
    if (count[c.name] < 2 || c.best_for) return c;
    const notes = Object.entries((parts[i] && parts[i].notes) || {})
      .filter(([k, v]) => v && !/количеств|^кол|дата|альтернат/i.test(k) && !/альтернат|не производ/i.test(String(v)))
      .map(([, v]) => String(v).trim());
    const note = notes.find(v => /цилиндр|лев|прав|сторон|ряд|банк|верх|нижн|передн|задн/i.test(v)) || notes[0];
    return note ? { ...c, best_for: note.length > 90 ? note.slice(0, 88) + '…' : note } : c;
  });
}

/** Adds diagram cards to the reply's PRODUCTS block (creates it if needed); the AI's own cards stay first. */
/**
 * Several parts in one message (Диалоги ✗ 06.11 #175, 230i F22 by VIN: gasket, flange,
 * oil filter, ATF pan, spark plugs): the catalog found rows for the intake gasket
 * (in the price list), but the AI showed cards for 3 parts and wrote «в каталоге с фото
 * этих позиций сейчас нет … уточню у специалиста». Code now: every asked part whose
 * catalog rows are in the price list gets its card(s) (max 2), the card line names the
 * part as the BMW catalog calls it; the AI's sentences calling that part missing go.
 * A part with no rows at all that the text no longer mentions gets one honest line. Pure.
 */
const MISSING_TALK_RE = /нет(?![а-яё])|не\s+(наш|наход|нашл|удалось)|отсутств|уточн|специалист|менеджер|запрос/i;
const kwStems = kw => String(kw || '').toLowerCase().replace(/ё/g, 'е').split(/[^a-zа-я0-9]+/)
  .filter(w => w.length >= 4).map(w => w.slice(0, Math.min(5, w.length - 1)));
const mentionsKw = (sentence, kw) => {
  const s = String(sentence || '').toLowerCase().replace(/ё/g, 'е'), st = kwStems(kw);
  return st.length > 0 && st.filter(x => s.includes(x)).length >= Math.min(2, st.length);
};
function ensureCardPerKeyword(text, { keywords, parts, feedByOem, carLabel }) {
  const kws = [...new Set((keywords || []).map(k => String(k || '').trim()).filter(Boolean))];
  if (kws.length < 2) return text;
  const norm = x => String(x || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  const re = /<<<PRODUCTS>>>([\s\S]*?)<<<END_PRODUCTS>>>/;
  const m = String(text || '').match(re);
  let cards = [];
  if (m) { try { const j = JSON.parse(m[1].trim()); if (Array.isArray(j)) cards = j; } catch { cards = []; } }
  const shown = new Set(cards.map(c => norm(c && (c.article || (c.diagram && c.diagram.oem)))));
  const rowsOf = kw => (parts || []).filter(p => String(p.query || '').toLowerCase().split(/\s*,\s*/).includes(kw.toLowerCase()));
  const added = [], empty = [];
  for (const kw of kws) {
    const rows = rowsOf(kw);
    if (!rows.length) { empty.push(kw); continue; }
    if (rows.some(p => shown.has(norm(p.oem)))) continue;
    const inFeed = rows.filter(p => feedByOem.get(norm(p.oem)));
    if (!inFeed.length) continue; // not in the price list -> diagram cards cover it
    for (const p of inFeed.slice(0, 2)) {
      const f = feedByOem.get(norm(p.oem));
      shown.add(norm(p.oem));
      cards.push({
        article: f.article, name: f.name, brand: f.brand, category: f.category,
        compatibility: carLabel ? `${carLabel} — по оригинальному каталогу BMW` : 'по оригинальному каталогу BMW',
        price: f.price, stock: f.stock, url: f.url, picture: f.picture,
        best_for: `Ваш запрос «${kw}». В каталоге BMW: «${p.name || f.name}»${p.unit ? `, узел «${p.unit}»` : ''}.`,
      });
    }
    added.push(kw);
  }
  if (!added.length) return text;
  console.log(`[chat] asked parts without a card -> added by code: ${added.join(', ')}`);
  let removed = 0;
  let out = String(text).split(/(<<<[A-Z_]+>>>[\s\S]*?<<<END_[A-Z_]+>>>|<<<MANAGER_BUTTON>>>|<<<CONTACT_FORM>>>)/).map((part, i) => i % 2 ? part
    : part.split('\n').map(line => line.split(/(?<=[.!?…])\s+/).filter(x => {
      const bad = MISSING_TALK_RE.test(x) && added.some(kw => mentionsKw(x, kw));
      if (bad) removed++;
      return !bad;
    }).join(' ')).join('\n').replace(/^\s*-{3,}\s*$/gm, '').replace(/\n{3,}/g, '\n\n')).join('');
  if (removed) console.log(`[chat] ${removed} sentence(s) calling a found part missing removed`);
  const prose = out.split(/<<<[A-Z_]+>>>[\s\S]*?<<<END_[A-Z_]+>>>|<<<MANAGER_BUTTON>>>|<<<CONTACT_FORM>>>/).join(' ');
  const unmentioned = empty.filter(kw => !mentionsKw(prose, kw));
  const block = `<<<PRODUCTS>>>\n${JSON.stringify(cards)}\n<<<END_PRODUCTS>>>`;
  out = m ? out.replace(re, block) : `${out.trim()}\n${block}`;
  if (unmentioned.length) {
    const line = `По ${unmentioned.length > 1 ? 'позициям' : 'позиции'} ${unmentioned.map(k => `«${k}»`).join(', ')} в оригинальном каталоге для вашего автомобиля ничего не нашлось — уточните, пожалуйста, название детали, или менеджер подберёт её по VIN.`;
    out = out.replace('<<<PRODUCTS>>>', `${line}\n<<<PRODUCTS>>>`);
  }
  return out;
}

function mergeDiagramCards(text, extra) {
  const re = /<<<PRODUCTS>>>([\s\S]*?)<<<END_PRODUCTS>>>/;
  const m = String(text || '').match(re);
  let cards = [];
  if (m) { try { const j = JSON.parse(m[1]); if (Array.isArray(j)) cards = j; } catch { cards = []; } }
  const have = new Set(cards.map(c => c && c.article ? laximo.normalizeOem(c.article) : '').filter(Boolean));
  const all = [...cards, ...extra.filter(c => !have.has(laximo.normalizeOem(c.article)))];
  const block = `<<<PRODUCTS>>>\n${JSON.stringify(all)}\n<<<END_PRODUCTS>>>`;
  return m ? text.replace(re, block) : `${text}\n${block}`;
}

/**
 * Card replies (diagram cards): the cards show every number, price and delivery
 * time, so the reply text keeps only what they don't (owner 30.10, live: DeepSeek
 * still listed 34218855007 / 34216864899 and wrote «Их карточки ниже покажет
 * система»). Drops every sentence (or list line) that contains a part number or
 * a ₽ price, or talks about the system / missing photos / cards; keeps the rest.
 * Nothing left -> one plain line. Text outside the special blocks only.
 */
const CARD_TALK_RE = /показан\S*\s+(\S+\s+){0,2}карточк|вместо\s+фото|систем[аеуы]\s+(сам|покаж|добав|автомат|вывед|отобраз)|покаж(ет|ут)\s+(систем|ниже)|без\s+фото|нет\s+(подтвержд\S*\s+)?карточк|карточк\S*\s+(с\s+фото|нет)|в\s+блок|«?открыть\s+деталь»?|кнопк\S*\s+«?открыть|нет\s+в\s+(каталоге|прайс)/i;
const PART_NO_RE = /(?<![0-9A-Za-z])\d{2}\s?\d{2}\s?\d\s?[0-9A-Z]{3}\s?[0-9A-Z]{3}(?![0-9A-Za-z])/;
const PART_NO_G = new RegExp(PART_NO_RE.source, 'g');
function stripNumbers(x) {
  return x
    .replace(/\(?\s*(?:от\s+)?\d[\d\s]*(?:[.,]\d+)?\s*₽\s*(?:,?\s*(?:срок\s*)?~?\s*\d+\s*(?:дн\.?|дней|дня))?\s*\)?/gi, ' ')
    .replace(new RegExp(`(?:арт\\.?|артикул|№|номер)?\\s*${PART_NO_RE.source}`, 'gi'), ' ')
    .replace(/\*\*\s*\*\*/g, ' ')
    .replace(/^(\s*[-•*]\s+)[—–-]\s+/gm, '$1') // «- — Эмблема» after the number was cut (Диалоги #325)
    .replace(/\(\s*[,;:—–-]?\s*\)/g, ' ')
    .replace(/\s+([,.;:!?)])/g, '$1').replace(/([(])\s+/g, '$1')
    .replace(/[,;]\s*(?=[,;.])/g, '').replace(/\s*[—–-]\s*([,.;]|$)/g, '$1').replace(/:\s*([,.]|$)/g, '$1')
    .replace(/\s{2,}/g, ' ').trim().replace(/\s*[,;:—–-]+$/, '');
}
const STALL_RE = /(сейчас|минут|секунд|момент)\S*\s+(провер|посмотр|подбер|найд|уточн)|^\s*(принял|понял|хорошо|ок)[,.!]?\s+(сейчас|провер)|подожд/i;

const MANAGER_DETAILS_RE = /менеджер\S*[^.!?\n]{0,40}(уточн|подтверд|сообщ|подскаж|расскаж|проверит)\S*[^.!?\n]{0,40}(срок|налич|цен|стоимост|достав)|(срок|налич|цен|стоимост|достав)\S*[^.!?\n]{0,40}(уточн|подтверд|сообщ|подскаж)\S*[^.!?\n]{0,30}менеджер/i;
/** Drops sentences «менеджер уточнит сроки / наличие / цену» from the prose (not from blocks). Pure. */
function dropManagerDetailsLine(text) {
  let n = 0;
  const out = String(text || '').split(/(<<<[A-Z_]+>>>[\s\S]*?<<<END_[A-Z_]+>>>|<<<MANAGER_BUTTON>>>|<<<CONTACT_FORM>>>)/).map((part, i) => i % 2 ? part
    : part.split('\n').map(line => line.split(/(?<=[.!?…])\s+/).filter(x => { const hit = MANAGER_DETAILS_RE.test(x); if (hit) n++; return !hit; }).join(' ')).join('\n').replace(/\n{3,}/g, '\n\n')).join('');
  if (n) console.log(`[chat] ${n} «менеджер уточнит сроки/цену» sentence(s) removed (cards show them)`);
  return n ? out.trim() : text;
}

function cleanCardsText(text, fallback) {
  const parts = String(text || '').split(/(<<<[A-Z_]+>>>[\s\S]*?<<<END_[A-Z_]+>>>|<<<MANAGER_BUTTON>>>|<<<CONTACT_FORM>>>)/);
  let removed = 0;
  for (let i = 0; i < parts.length; i += 2) {
    const lines = parts[i].split('\n').map(line => {
      // «**Фланец** — арт. 11118511205.» (Диалоги 06.11 #175): no split after «арт.» --
      // the number alone went as a sentence and «— арт.» was left in the text.
      const sentences = line.split(/(?<=[.!?…])(?<![Аа]рт\.)(?<!(?:^|\*\*|\s)\d{1,2}\.)\s+/); // nor after a list number «**1.» (live 06.11)
      // A sentence about the system / cards goes; numbers and prices are cut out of
      // the others, which stay if real words are left (live 30.10: the whole
      // «**Задняя ось** — колодки 34218855007 …» line went, so the text named only
      // the front axle).
      const keep = [];
      for (const x of sentences) {
        if (CARD_TALK_RE.test(x)) { removed++; continue; }
        if (!(PART_NO_RE.test(x) || /\d\s*₽/.test(x))) { keep.push(x); continue; }
        const y = stripNumbers(x);
        if ((y.match(/[А-ЯЁа-яё]{3,}/g) || []).length >= 2) keep.push(y); else removed++;
      }
      return keep.join(' ');
    });
    parts[i] = lines.filter((l, j) => l.trim() || (j > 0 && lines[j - 1].trim()))
      .filter(l => !/^\s*[-•*–]?\s*\**[^*]{0,40}:\**\s*$/.test(l)) // headings left without their list
      .join('\n').replace(/\n{3,}/g, '\n\n');
  }
  let out = parts.join('');
  const prose = out.split(/<<<[A-Z_]+>>>[\s\S]*?<<<END_[A-Z_]+>>>|<<<MANAGER_BUTTON>>>|<<<CONTACT_FORM>>>/).join('').trim();
  // «Принял, сейчас проверю по VIN.» + 10 cards (Диалоги 06.11, #107): the check is
  // already done -- a stall line alone is replaced by the real summary line.
  if (!prose || (prose.length < 90 && STALL_RE.test(prose))) {
    if (prose) { out = out.replace(prose, '').trim(); console.log(`[chat] stall reply «${prose}» replaced by the summary line`); }
    out = `${fallback}\n${out.trim()}`;
  }
  if (removed) console.log(`[chat] card reply: ${removed} sentence(s) with numbers/prices/system talk removed`);
  return out.trim();
}

/** One carousel in a fixed order: front axle, rear axle, the rest; alternatives last within each. */
function sortCardsByAxle(text, catalogParts) {
  const re = /<<<PRODUCTS>>>([\s\S]*?)<<<END_PRODUCTS>>>/;
  const m = String(text || '').match(re);
  if (!m) return text;
  let cards;
  try { cards = JSON.parse(m[1]); } catch { return text; }
  if (!Array.isArray(cards) || cards.length < 2) return text;
  const byOem = new Map((catalogParts || []).filter(p => p && p.oem).map(p => [laximo.normalizeOem(p.oem), p]));
  const rank = c => {
    const p = c && c.article ? byOem.get(laximo.normalizeOem(c.article)) : null;
    const axle = p && p.axle === 'передняя ось' ? 0 : p && p.axle === 'задняя ось' ? 1 : 2;
    return axle * 3 + (p && p.crossSell ? 2 : p && p.alternative ? 1 : 0);
  };
  const sorted = cards.map((c, i) => ({ c, i })).sort((a, b) => rank(a.c) - rank(b.c) || a.i - b.i).map(x => x.c);
  return sorted.some((c, i) => c !== cards[i]) ? text.replace(re, `<<<PRODUCTS>>>\n${JSON.stringify(sorted)}\n<<<END_PRODUCTS>>>`) : text;
}

/** Alternative accessories and kits with sensor: labelled cards, alternatives after the standard parts. */
function labelVariantCards(text, catalogParts) {
  const alt = new Set(), kit = new Set(), cross = new Map();
  for (const p of catalogParts || []) {
    if (!p || !p.oem) continue;
    if (p.crossSell) cross.set(laximo.normalizeOem(p.oem), p.crossSell);
    else if (p.alternative) alt.add(laximo.normalizeOem(p.oem));
    else if (p.kitWithSensor) kit.add(laximo.normalizeOem(p.oem));
  }
  if (!alt.size && !kit.size && !cross.size) return text;
  const re = /<<<PRODUCTS>>>([\s\S]*?)<<<END_PRODUCTS>>>/;
  const m = String(text || '').match(re);
  if (!m) return text;
  let cards;
  try { cards = JSON.parse(m[1]); } catch { return text; }
  if (!Array.isArray(cards)) return text;
  let changed = 0;
  for (const c of cards) {
    const k = c && c.article ? laximo.normalizeOem(c.article) : null;
    if (k && cross.has(k) && !/^Нужн/.test(c.best_for || '')) { c.best_for = cross.get(k) === 'paste' ? 'Нужна при замене колодок — по каталогу BMW.' : 'Нужен при замене колодок — по каталогу BMW.'; changed++; }
    else if (k && alt.has(k) && !/^Альтернатива/.test(c.best_for || '')) { c.best_for = `Альтернатива (оригинальная принадлежность BMW).${c.best_for ? ' ' + c.best_for : ''}`; changed++; }
    else if (k && kit.has(k) && !/датчик/i.test(c.best_for || '')) { c.best_for = `Комплект с датчиком износа.${c.best_for ? ' ' + c.best_for : ''}`; changed++; }
  }
  const ordered = [...cards.filter(c => !(c && c.article && alt.has(laximo.normalizeOem(c.article)))), ...cards.filter(c => c && c.article && alt.has(laximo.normalizeOem(c.article)))];
  const moved = ordered.some((c, i) => c !== cards[i]);
  if (!changed && !moved) return text;
  return text.replace(re, `<<<PRODUCTS>>>\n${JSON.stringify(ordered)}\n<<<END_PRODUCTS>>>`);
}
/** Removes the widget's history placeholders from a reply, with the empty lines they leave. */
function stripHistoryPlaceholders(text) {
  return String(text || '')
    .replace(/[ \t]*\[(запчасти|схема|схемы|товары|карточки) показан[аыо]?\][ \t]*/gi, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

async function extractVehicleInfo(messages) {
  const transcript = messages
    .map(m => `${m.role === 'user' ? 'Клиент' : 'Ассистент'}: ${typeof m.content === 'string' ? m.content : JSON.stringify(m.content)}`)
    .join('\n');

  // Reading the request (part words, the catalog search names, BMW groups) on
  // LLM_MODEL. 30.10: single model, no fallback -- a failure returns {}.
  const call = async (model, body, ms) => {
    const started = Date.now();
    const res = await llmFastFetch({ model, ...body, messages: [{ role: 'user', content: EXTRACT_PROMPT + transcript }] }, ms);
    if (!res.ok) throw await llmHttpError(model, res);
    const data = await res.json();
    trackUsage(model, data);
    const raw = ((data.content || []).find(b => b.type === 'text') || {}).text || '';
    const m = raw.replace(/```json|```/g, '').match(/\{[\s\S]*\}/);
    if (!m) throw new Error(`${model}: no JSON (stop: ${data.stop_reason})`);
    const out = JSON.parse(m[0]);
    console.log(`[extract] ${model}: ${Date.now() - started} ms`);
    return out;
  };
  // One model, no fallback model. On failure: the previous message's extraction
  // for this conversation (see previousExtraction), else {}.
  try {
    let out;
    try {
      out = await call(LLM_MODEL, { max_tokens: 8000 }, EXTRACT_TIMEOUT_MS);
    } catch (err) {
      if (!retryableLlmError(err)) throw err;
      console.warn(`[extract] ${LLM_MODEL} first try failed (${err.message}) -- trying once more`);
      out = await call(LLM_MODEL, { max_tokens: 8000 }, EXTRACT_RETRY_TIMEOUT_MS);
      console.log('[extract] second try succeeded');
    }
    // A button answer to our own question («Нет», «Есть», «Передние», «X5 40iX»…)
    // often comes back without the part (live 04.11: «Нет» to the equipment
    // question for a battery -> partKeywords null -> no search, «код двигателя?»).
    // Then the part of the previous message is kept.
    if (out && !(out.partKeywords && out.partKeywords.length)) {
      const lastA = String((([...(messages || [])].reverse().find(m => m.role === 'assistant')) || {}).content || '');
      if ([EQUIP_LEAD, CLARIFY_LEAD, AXLE_LEAD, SIDE_LEAD, VARIANT_LEAD].some(l => lastA.includes(l))) {
        const prev = previousExtraction(messages);
        if (prev && prev.partKeywords && prev.partKeywords.length) {
          out.partKeywords = prev.partKeywords;
          out.partSearchNames = out.partSearchNames || prev.partSearchNames || null;
          out.partGroups = out.partGroups || prev.partGroups || null;
          if (!out.vin && prev.vin) out.vin = prev.vin;
          if (!out.model && prev.model) out.model = prev.model;
          if (!out.brand && prev.brand) out.brand = prev.brand;
          console.log(`[extract] answer to our question -- part kept from the previous message: ${out.partKeywords.join(', ')}`);
        }
      }
    }
    rememberExtraction(messages, out);
    return out;
  } catch (err) {
    if (!isAccountError(err.status)) console.error(`[extract] ${LLM_MODEL} failed: ${err.message}`); // account errors already logged
    const prev = previousExtraction(messages);
    if (prev) {
      console.log(`[extract] reusing the previous message's extraction (${[prev.brand, prev.model].filter(Boolean).join(' ') || 'no car'}${prev.vin ? ', VIN ' + prev.vin : ''})`);
      rememberExtraction(messages, prev);
      return prev;
    }
    return {}; // safe fallback -- matching below just yields nothing, agent keeps asking clarifying questions
  }
}


function engineCodesOverlap(userCode, recordCode) {
  if (!userCode || !recordCode) return true;
  // Split ONLY on commas -- a comma genuinely separates multiple distinct
  // codes (e.g. "CJCD,CSUA"), but whitespace does NOT: some codes contain
  // internal spaces as part of a single code (e.g. BMW's "M54 B22"), and
  // splitting on whitespace was wrongly fragmenting those into two tokens
  // that never matched the stored no-space form ("M54B22") -- this was
  // intermittent (not a constant failure) because the extraction step
  // doesn't always format the code identically across calls, sometimes
  // preserving the display's internal space and sometimes not.
  // normalizeApprovalCode() strips ALL internal whitespace/punctuation, so
  // "M54 B22" and "M54B22" always compare equal regardless of which form
  // extraction happens to produce.
  const userCodes   = userCode.split(',').map(normalizeApprovalCode).filter(Boolean);
  const recordCodes = recordCode.split(',').map(normalizeApprovalCode).filter(Boolean);
  return recordCodes.some(rc => userCodes.some(uc => uc === rc || uc.includes(rc) || rc.includes(uc)));
}

// Parses the compatibility table's `years` field, e.g. "2004/04 - 2006/09"
// (also tolerates an open-ended side, e.g. "2015/04 -" for a still-in-
// production model, or a missing/malformed value). Only the YEAR portion
// is used -- the model doesn't need month precision, and customers/Haiku's
// extraction never provide a production month anyway. Returns null if the
// string can't be parsed at all (record is then treated as "no year data",
// i.e. NOT filtered out -- see yearOverlaps below -- since an unparseable
// value is a data-quality gap, not evidence the vehicle doesn't fit).
function parseYearRange(yearsStr) {
  if (!yearsStr) return null;
  const parts = String(yearsStr).split('-').map(s => s.trim());
  const parseYear = (s) => {
    const m = s && s.match(/(\d{4})/);
    return m ? parseInt(m[1], 10) : null;
  };
  const from = parseYear(parts[0]);
  const to   = parts.length > 1 ? parseYear(parts[1]) : from;
  if (from === null && to === null) return null;
  return { from: from ?? -Infinity, to: to ?? Infinity };
}

// True if the customer's stated year falls inside the record's production
// range -- this is what actually distinguishes BMW's X5 generations (E53
// 1999-2006, E70 2006-2013, F15 2013-2018, G05 2018+) from each other,
// since normalizeModel()'s substring match on "X5" alone matches all of
// them equally (chassis code is rarely present in what the customer says).
// Added 2026-08-12 after confirming via production logs that a single
// "BMW X5 2008" + one part-category query was matching 137 vendorCodes/
// ~130k compatibility rows -- almost entirely different X5 generations
// that were never actually asked about. Deliberately permissive when data
// is missing on EITHER side (no user year, or an unparseable/absent
// `years` field) -- absence of information should fall through to the
// existing brand/model/engine filters rather than silently drop a
// possibly-correct match.
function yearOverlaps(userYear, recordYearsStr) {
  if (!userYear) return true;
  const range = parseYearRange(recordYearsStr);
  if (!range) return true;
  const y = parseInt(userYear, 10);
  if (isNaN(y)) return true;
  return y >= range.from && y <= range.to;
}



// Crude Russian stemming: truncates a word to tolerate case/gender/number
// endings (тормозНЫЕ/тормозНАЯ/тормозНОГО/тормозНОЙ all share the root
// "тормоз"). NOT linguistically rigorous -- just chops a fixed number of
// trailing characters off longer words -- but it's cheap, deterministic,
// and good enough to stop exact-word-form mismatches from silently
// dropping real matches. Left short/ambiguous words (<=4 chars) alone,
// since stemming those risks matching unrelated words.
function stemRu(word) {
  if (word.length <= 4) return word;
  return word.slice(0, Math.max(4, word.length - 2));
}

// Narrows an already vehicle-matched catalog slice down to the specific
// part(s) the customer is asking about. Without this, matchCompatibility()
// returns every vendorCode that fits the customer's vehicle regardless of
// part type -- as the compatibility catalog grows to cover more part
// categories, that set (and therefore the prompt) grows with total catalog
// size instead of staying scoped to the actual question. This is a plain
// substring match against the catalog's own `name`/`category` fields (both
// in Russian, matching how ABCP's feed stores them) -- cheap, deterministic,
// no LLM retrieval involved, same principle as the vehicle-matching layer.
//
// Accepts a LIST of keywords (OR'd together), not a single keyword --
// broad requests like "everything needed for a service" get expanded by
// the extraction prompt into several concrete categories (oil filter, air
// filter, spark plugs...) rather than one term that matches nothing.
//
// Uses stemRu() (see above) on both the keyword tokens and the haystack
// words -- confirmed real incident: customer asked for "тормозные
// колодки" (brake pads); the correct catalog products were named "Рем.
// к-т торм.накладок" (abbreviated "торм." + a genuinely different word,
// "накладок" not "колодки") -- neither the grammatical ending nor the
// word itself matched exactly, so the real match was silently dropped
// and only an unrelated handbrake-shoe kit (which happened to contain the
// literal word "колодки") got recommended instead. Stemming plus the
// накладки synonym now added to the extraction prompt (see EXTRACT_PROMPT
// above) together close this specific gap; stemming alone also helps
// generically with other Russian case-ending mismatches we haven't hit
// yet.
// RU->EN part-keyword translations. Confirmed real incident (2026-08-14):
// a customer asked for "лобовое стекло" (windshield) on a BMW X6 E71 --
// vehicle matching correctly found the vendorCode, but the ABCP feed names
// this specific product entirely in English ("Green windshield, shade
// band+rain sensor"), so the Russian keyword tokens never shared a
// substring with the (Latin-only) haystack tokens and the real match was
// silently dropped. The ABCP feed mixes Russian- and English-named
// products, so this isn't a one-off -- any English-named item is invisible
// to Russian keyword search without this.
// Kept as a small hardcoded map rather than a translation API call: cheap,
// deterministic, no added latency/cost per request. Part-type vocabulary
// is a closed, slow-growing list -- extend as new gaps are confirmed via
// missing_articles / production logs, same as the накладки synonym above.
const PART_KEYWORD_RU_EN = {
  'СТЕКЛО':      ['GLASS', 'WINDSHIELD', 'WINDOW'],
  'ЛОБОВОЕ':     ['WINDSHIELD', 'FRONT'],
  'БАМПЕР':      ['BUMPER'],
  'ФАРА':        ['HEADLIGHT', 'HEADLAMP'],
  'ФОНАРЬ':      ['LIGHT', 'LAMP', 'TAILLIGHT'],
  'ЗЕРКАЛО':     ['MIRROR'],
  'КАПОТ':       ['HOOD', 'BONNET'],
  'ДВЕРЬ':       ['DOOR'],
  'РЕШЕТКА':     ['GRILLE', 'GRILL'],
  'РАДИАТОР':    ['RADIATOR'],
  'АМОРТИЗАТОР': ['SHOCK', 'ABSORBER', 'STRUT'],
  'ТОРМОЗНОЙ':   ['BRAKE'],
  'КОЛОДКИ':     ['PAD', 'PADS'],
  'ДИСК':        ['DISC', 'DISK', 'ROTOR'],
  'ФИЛЬТР':      ['FILTER'],
  'РЕМЕНЬ':      ['BELT'],
  'ПОДШИПНИК':   ['BEARING'],
  'ГЛУШИТЕЛЬ':   ['MUFFLER', 'EXHAUST'],
  'СВЕЧА':       ['SPARK', 'PLUG'],
  'ДАТЧИК':      ['SENSOR'],
  'НАСОС':       ['PUMP'],
  'ФИЛЬТРУЮЩИЙ': ['FILTER'],
};

// Expands a keyword word with any known EN equivalents (see
// PART_KEYWORD_RU_EN above), alongside its normal stemmed form. Looked up
// against the raw uppercase word (not the stemmed one) since the
// dictionary keys are full words -- stemming Cyrillic first and matching
// that against a dictionary keyed on full words would just add another
// way to miss.
function expandWithEnglish(rawWord) {
  const enMatches = PART_KEYWORD_RU_EN[rawWord];
  return enMatches ? [stemRu(rawWord), ...enMatches] : [stemRu(rawWord)];
}

function filterCatalogByPartKeyword(catalogArray, partKeywords) {
  if (!partKeywords || !partKeywords.length) return catalogArray; // nothing to narrow by yet -- caller decides whether that's safe to send as-is
  const keywordTokenLists = partKeywords
    .map(k => (k || '').toUpperCase().replace(/Ё/g, 'Е').trim().split(/\s+/).filter(Boolean))
    .filter(words => words.length)
    .map(words => words.flatMap(expandWithEnglish));
  if (!keywordTokenLists.length) return catalogArray;
  return catalogArray.filter(p => {
    const haystackWords = `${p.name || ''} ${p.category || ''}`
      .toUpperCase().replace(/Ё/g, 'Е') // Ё isn't in А-Я: "ЩЁТКИ" split into "Щ" + "ТКИ"
      .split(/[^A-ZА-Я0-9]+/)
      .filter(Boolean)
      .map(stemRu);
    return keywordTokenLists.some(tokens =>
      // (a 1-2 letter word of the name, e.g. "к"/"т" from "рем.к-т", must not
      // match every keyword containing that letter)
      tokens.some(tok => haystackWords.some(hw => hw.includes(tok) || (hw.length >= 3 && tok.includes(hw))))
    );
  });
}

// Logs vendorCodes that fit a customer's vehicle but are absent from the
// client's catalog feed (see call site above -- almost always the
// no-photo export exclusion). One row per vendorCode ("missing_articles"
// table), incremented/updated on every occurrence rather than logged as a
// full history -- keeps the dashboard sorted by "most requested" so the
// client can prioritize which photos to add first, instead of scrolling
// an unsorted event log.
//
// Uses PostgREST's upsert (Prefer: resolution=merge-duplicates) plus a
// Postgres function bump for the increment -- see abcp-catalog-proxy /
// dashboard setup SQL for the missing_articles table + bump_missing_article
// function definitions. Never throws into the caller -- this is a
// best-effort side log, not something that should ever affect the actual
// chat response.
async function logMissingArticles(vendorCodes, extracted) {
  if (!SUPABASE_URL || !SUPABASE_SERVICE_KEY) {
    console.error('logMissingArticles: SUPABASE_URL or SUPABASE_SERVICE_KEY is not set in this deployment\'s environment');
    return;
  }

  const vehicleInfo = {
    brand:      extracted.brand      || null,
    model:      extracted.model      || null,
    year:       extracted.year       || null,
    engineCode: extracted.engineCode || null,
  };

  // Cap + batch. Confirmed real incident: a single vehicle-wide match can
  // legitimately have 200+ vendorCodes that fit the vehicle but aren't in
  // the catalog (e.g. a common model with a large compatibility footprint
  // but sparse photo coverage). The original code fired one fetch() per
  // vendorCode via a single unbounded Promise.all -- for ~213 missing
  // vendorCodes that's ~213 simultaneous outbound HTTPS connections from
  // one invocation, which blew through the serverless container's file
  // descriptor limit (EMFILE) and took the NEXT unrelated Supabase call
  // (fetchOilProducts) down with it in the same request.
  //
  // MAX_PER_REQUEST also makes sense on its own terms, independent of the
  // resource-exhaustion angle: logging 200+ "missing" parts from one
  // customer query is noise, not a useful worklist entry for the client --
  // most of those 200 have nothing to do with what was actually asked.
  const MAX_PER_REQUEST = 25;
  const BATCH_SIZE      = 5;
  const toLog = vendorCodes.slice(0, MAX_PER_REQUEST);
  if (vendorCodes.length > MAX_PER_REQUEST) {
    console.warn(`logMissingArticles: capping ${vendorCodes.length} missing vendorCodes to ${MAX_PER_REQUEST} for this request`);
  }

  for (let i = 0; i < toLog.length; i += BATCH_SIZE) {
    const batch = toLog.slice(i, i + BATCH_SIZE);
    await Promise.all(batch.map(async (vendorCode) => {
      try {
        const res = await fetch(
          `${SUPABASE_URL.replace(/\/?$/, '/')}rest/v1/rpc/bump_missing_article`,
          {
            method:  'POST',
            headers: {
              'apikey':        SUPABASE_SERVICE_KEY,
              'Authorization': `Bearer ${SUPABASE_SERVICE_KEY}`,
              'Content-Type':  'application/json',
            },
            body: JSON.stringify({
              p_vendor_code:  vendorCode,
              p_vehicle_info: vehicleInfo,
            }),
            signal: AbortSignal.timeout(8000),
          }
        );
        if (!res.ok) {
          console.error('bump_missing_article failed:', vendorCode, await res.text());
        }
      } catch (err) {
        console.error('bump_missing_article error:', vendorCode, err.message, err.cause || '');
      }
    }));
  }
}

function matchCompatibility(compatibilityData, extracted) {
  const matched = {};

  if (extracted.vendorCode && compatibilityData[extracted.vendorCode]) {
    matched[extracted.vendorCode] = compatibilityData[extracted.vendorCode];
    return matched;
  }

  if (!extracted.brand && !extracted.model) return matched;

  const userBrand = (extracted.brand || '').toUpperCase().trim();
  const userModelNorm = normalizeModel(extracted.model);  
  console.log("User model:", extracted.model);
console.log("Normalized:", userModelNorm);
  const userModelTokens = userModelNorm.split(' ').filter(Boolean);

  for (const [vendorCode, records] of Object.entries(compatibilityData)) {
  const hits = records.filter(r => {
    if (userBrand && r.brand?.toUpperCase().trim() !== userBrand) {
      return false;
    }

    if (userModelTokens.length) {
      // Search BOTH model and modificationName because different
      // manufacturers store the trim in different fields.
      // Examples:
      //   Audi: model="A4 (B8)", modificationName="2.0 TDI quattro"
      //   BMW:  model="3 (E46)", modificationName="320 i"

      const recordSearchNorm = normalizeModel(
        `${r.model} ${r.modificationName || ''}`
      );

      // Remove spaces so that:
      // 320i == 320 i
      // 330xd == 330 xd
      // 740Li == 740 Li
      const recordCompact = recordSearchNorm.replace(/\s+/g, '');

      const modelOk = userModelTokens.every((tok, idx) => {
        const tokenCompact = tok.replace(/\s+/g, '');
        // Short/bare series tokens ("3", "5", "X1"...) are too easy to
        // accidentally substring-match against unrelated digits elsewhere
        // in the compacted record string once trim/engine suffixes are
        // squashed together (e.g. token "3" matching inside "530D" from
        // a completely different 5-series record). Confirmed real
        // incident: a customer who'd only said "BMW 3" so far (no
        // chassis/trim yet) was matching 5-series and other unrelated
        // records purely because their model number contained a "3"
        // somewhere. For tokens this short, require an exact match
        // against the record's OWN series (its model string before any
        // "(" or trim) instead of an anywhere-substring check. Longer
        // tokens (chassis codes, merged trim numbers like "320I") keep
        // the substring check, since that's what makes "320i"=="320 i"
        // matching work in the first place.
        //
        // IMPORTANT: only apply this strict check to the FIRST token
        // (idx === 0) -- the series identifier always comes first in
        // userModelTokens. Applying it to every short token also caught
        // engine-displacement fragments that end up isolated after
        // normalizeModel()'s "." -> " " punctuation step, e.g. "4.4i"
        // becomes tokens ["4", "4I"] -- that bare "4" was being compared
        // as if it were a series number and (correctly) never equaled
        // the record's actual series ("X5"), silently rejecting genuine
        // matches for the customer's own vehicle. Confirmed real
        // incident: BMW X5 E53 4.4i (N62B44) matched zero compatibility
        // rows despite an exact record existing, purely because of this.
        // Non-leading short tokens now fall through to the plain
        // substring check instead, same as longer tokens.
        if (idx === 0 && tokenCompact.length <= 2) {
          const recordSeriesToken = normalizeModel(extractSeries(r.model)).replace(/\s+/g, '');
          return recordSeriesToken === tokenCompact;
        }
        return recordCompact.includes(tokenCompact);
      });


      if (!modelOk) {
        return false;
      }
    }

    // Engine code match
    if (
      extracted.engineCode &&
      !engineCodesOverlap(extracted.engineCode, r.engineCode)
    ) {
      return false;
    }

    // Production-year match -- see yearOverlaps() above. Without this,
    // "X5" (or any model name) matches every generation of that model
    // equally, since chassis codes are rarely present in what the
    // customer actually says.
    if (extracted.year && !yearOverlaps(extracted.year, r.years)) {
      return false;
    }

    return true;
  });
    if (hits.length) matched[vendorCode] = hits;
  }

  return matched;
}

// ─── MANUAL PRODUCTS (oils/fluids, client-curated) ─────────────────────────
// See README's "Compatibility matching architecture" section for why this
// follows the same deterministic-matching pattern as vehicle compatibility
// rather than dumping the whole table into the prompt: searching a large
// embedded list for one matching approval code is a retrieval task, which
// both Haiku and Sonnet 5 were unreliable at for the vehicle-fitment case.
// Same fix applies here -- match in plain JS, hand Claude only the result.

let oilProductsCache    = null;
let oilProductsCachedAt = 0;
const OIL_PRODUCTS_TTL_MS = 15 * 60 * 1000; // 15 min -- client adds products manually, doesn't change often

async function fetchOilProducts() {
  if (!SUPABASE_URL || !SUPABASE_SERVICE_KEY) {
    console.error('fetchOilProducts: SUPABASE_URL or SUPABASE_SERVICE_KEY is not set in this deployment\'s environment');
    return [];
  }

  const now = Date.now();
  if (oilProductsCache && (now - oilProductsCachedAt) < OIL_PRODUCTS_TTL_MS) {
    return oilProductsCache;
  }
  try {
    const url = `${SUPABASE_URL.replace(/\/?$/, '/')}rest/v1/manual_products?select=*`;
    const res = await fetch(url, {
      headers: {
        'apikey':        SUPABASE_SERVICE_KEY,
        'Authorization': `Bearer ${SUPABASE_SERVICE_KEY}`,
      },
      signal: AbortSignal.timeout(8000),
    });
    if (!res.ok) {
      console.error('fetchOilProducts: Supabase responded', res.status, await res.text().catch(() => ''));
      return oilProductsCache || [];
    }
    const data = await res.json();
    oilProductsCache    = data;
    oilProductsCachedAt = now;
    return data;
  } catch (err) {
    // "fetch failed" from Node hides the real cause (DNS, TLS, connection
    // refused, timeout...) -- err.cause carries the underlying error the
    // top-level message doesn't show. Previously this catch block was
    // fully silent, which meant a systemic Supabase connectivity problem
    // here looked identical to "just no oil products yet" -- confirmed
    // real incident: totalOilProducts silently dropped to 0 in production
    // logs with no error at all pointing to why.
    console.error('fetchOilProducts error:', err.message, err.cause || '');
    return oilProductsCache || [];
  }
}

// Normalizes an approval code for comparison: uppercase, strip all
// punctuation/whitespace. "VW 502.00", "VW 502 00", and "vw50200" all
// become "VW50200" -- this handles the inconsistent formatting seen across
// different products' "Допуски производителей" field.
function normalizeApprovalCode(code) {
  if (!code) return '';
  return code.toUpperCase().replace(/[^A-Z0-9А-Я]/g, '');
}

// Given the full manual_products list and a customer-stated approval code,
// return only the products whose "Допуски производителей" field contains
// that code -- brand-agnostic, exactly how real oil-compatibility works
// (a generic-brand oil carrying the right approval is just as valid as an
// OEM-branded one).
function matchOilByApproval(products, approvalCode) {
  const target = normalizeApprovalCode(approvalCode);
  if (!target) return [];

  return products.filter(p => {
    const approvalsField = p.specs?.['Допуски производителей'];
    if (!approvalsField) return false;
    const codes = approvalsField.split(',').map(c => normalizeApprovalCode(c));
    return codes.some(c => c === target || c.includes(target) || target.includes(c));
  });
}

// Given the full manual_products list and the extracted vehicle info,
// return products whose `fitment` array (set by the client in the
// dashboard, see products.js `set_fitment`) contains an entry matching the
// customer's vehicle. Only products WITH a non-empty fitment array are
// considered here -- products without one (e.g. most oils, matched
// instead by approval code above) are intentionally left untouched by
// this function so their existing brand/vehicle-agnostic behavior doesn't
// change. Reuses normalizeModel() so matching stays consistent with the
// ABCP vehicle-compatibility matching above (matchCompatibility) rather
// than introducing a second, subtly different comparison scheme.
function matchManualProductsByVehicle(products, extracted) {
  if (!extracted.brand && !extracted.model) return [];

  const userBrand       = (extracted.brand || '').toUpperCase().trim();
  const userModelNorm   = normalizeModel(extracted.model);
  const userModelTokens = userModelNorm.split(' ').filter(Boolean);
  const userYear        = extracted.year ? parseInt(extracted.year, 10) : null;

  return products.filter(p => {
    const fitmentList = Array.isArray(p.fitment) ? p.fitment : [];
    if (fitmentList.length === 0) return false; // no vehicle data on this product -- not vehicle-matchable

    return fitmentList.some(f => {
      if (userBrand && f.brand && f.brand.toUpperCase().trim() !== userBrand) {
        return false;
      }

      if (userModelTokens.length) {
        // Same series+modification search-string trick as matchCompatibility
        // (record.model + record.modificationName), just with this
        // fitment entry's own field names.
        const recordSearchNorm = normalizeModel(`${f.series || ''} ${f.modification || ''}`);
        const recordCompact    = recordSearchNorm.replace(/\s+/g, '');
        // Same fix as matchCompatibility (see its comment) -- short bare
        // tokens ("3", "5", "X1") must match this entry's OWN series
        // exactly, not substring-match anywhere in the compacted string,
        // or e.g. token "3" would match any fitment entry whose
        // modification happens to contain a "3" somewhere (like "530d").
        const modelOk = userModelTokens.every(tok => {
          const tokenCompact = tok.replace(/\s+/g, '');
          if (tokenCompact.length <= 2) {
            const recordSeriesToken = normalizeModel(f.series || '').replace(/\s+/g, '');
            return recordSeriesToken === tokenCompact;
          }
          return recordCompact.includes(tokenCompact);
        });
        if (!modelOk) return false;
      }

      if (userYear && (f.yearFrom || f.yearTo)) {
        const from = f.yearFrom ? parseInt(f.yearFrom, 10) : -Infinity;
        const to   = f.yearTo   ? parseInt(f.yearTo, 10)   : Infinity;
        if (userYear < from || userYear > to) return false;
      }

      return true;
    });
  });
}

// ─── CORS HEADERS ──────────────────────────────────────────────────────────────
function corsHeaders() {
  return {
    'Access-Control-Allow-Origin':  '*',
    'Access-Control-Allow-Methods': 'POST, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type',
    'Access-Control-Max-Age':       '86400',
  };
}

// ─── MAIN HANDLER ──────────────────────────────────────────────────────────────
// ─── COST PER MESSAGE (owner 28.10: compare Haiku+Sonnet vs Sonnet only) ───────
// Every Anthropic call of one chat message adds its token usage here; one log
// line per message: tokens per model + an estimate in $ (prices per million
// tokens from env PRICE_<MODEL>_IN / _OUT, defaults below -- check them on the
// Anthropic pricing page).
const { AsyncLocalStorage } = require('async_hooks');
const usageStore = new AsyncLocalStorage();
const DEFAULT_PRICES = { 'claude-sonnet-5': [3, 15], 'claude-haiku-4-5-20251001': [1, 5] };
// Models without a default (e.g. deepseek-v4-pro) need PRICE_<MODEL>_IN/_OUT in env
// (e.g. PRICE_DEEPSEEK_V4_PRO_IN). Until then their cost shows as "price not set"
// instead of a made-up number.
function priceOf(model) {
  const key = model.toUpperCase().replace(/[^A-Z0-9]+/g, '_');
  const d = DEFAULT_PRICES[model] || [null, null];
  const pin = process.env[`PRICE_${key}_IN`] ?? d[0];
  const pout = process.env[`PRICE_${key}_OUT`] ?? d[1];
  if (pin == null || pout == null) return null;
  return [Number(pin), Number(pout)];
}
function trackUsage(model, data) {
  const store = usageStore.getStore();
  const u = data && data.usage;
  if (!store || !u) return;
  // billed-equivalent input: cache writes ×1.25, cache reads ×0.1 of the input price
  const input = Math.round((u.input_tokens || 0) + 1.25 * (u.cache_creation_input_tokens || 0) + 0.1 * (u.cache_read_input_tokens || 0));
  store.push({ model, input, output: u.output_tokens || 0 });
}
function logUsage(calls) {
  if (!calls.length) return;
  const by = {};
  for (const c of calls) { const m = (by[c.model] ||= { calls: 0, input: 0, output: 0 }); m.calls++; m.input += c.input; m.output += c.output; }
  let usd = 0;
  const parts = Object.entries(by).map(([model, m]) => {
    const price = priceOf(model);
    if (!price) return `${model} ×${m.calls}: in ${m.input}, out ${m.output} (price not set: PRICE_${model.toUpperCase().replace(/[^A-Z0-9]+/g, '_')}_IN/_OUT)`;
    const cost = (m.input * price[0] + m.output * price[1]) / 1e6; usd += cost;
    return `${model} ×${m.calls}: in ${m.input}, out ${m.output} (~$${cost.toFixed(4)})`;
  });
  console.log(`[cost] message: ${parts.join(' | ')} | total ~$${usd.toFixed(4)} (~${(usd * 100).toFixed(2)} ¢)`);
}

// ─── Live progress stream ────────────────────────────────────────────────
// The widget sends `stream: true`: the reply becomes NDJSON (lib/progress.js)
// -- {"step": "..."} lines while the work runs, then one
// {"done": true, "status": N, "body": {...}} line with the usual JSON. Every
// existing `res.status(N).json(body)` exit is turned into that last line, so
// no return path needs to know about streaming. Without `stream: true` (old
// cached widgets, scripts) the response is plain JSON as before.
function streamResponse(res) {
  const setHeader = res.setHeader.bind(res);
  let open = false;
  let code = 200;
  const write = obj => {
    if (res.writableEnded || res.destroyed) return; // a late step from background work
    if (!open) {
      open = true;
      setHeader('Content-Type', 'application/x-ndjson; charset=utf-8');
      setHeader('Cache-Control', 'no-cache, no-transform');
      setHeader('X-Accel-Buffering', 'no'); // nginx: pass each line through at once
      Object.entries(corsHeaders()).forEach(([k, v]) => setHeader(k, v));
      res.statusCode = 200;
      res.flushHeaders();
    }
    res.write(JSON.stringify(obj) + '\n');
  };
  // After the first line the headers are gone; the exits' own setHeader calls are moot.
  res.setHeader = (k, v) => (open ? res : setHeader(k, v));
  res.status = c => { code = c; return res; };
  res.json = body => { write({ done: true, status: code, body }); res.end(); return res; };
  return { emit: text => write({ step: text }) };
}

/** «Понял запрос: тормозные колодки — BMW X5 E70» from the extraction (no AI call). */
function understoodStep(extracted, workshopTopic) {
  if (extracted.orderStatusQuestion === true || extracted.orderStatusQuestion === 'true') return null;
  if (workshopTopic) return workshopTopic === 'keys' ? 'Понял: вопрос про изготовление ключа' : 'Понял: вопрос про кодирование / прошивку';
  const car = [extracted.brand, extracted.model, extracted.engineCode].filter(Boolean).join(' ')
    || (laximo.normalizeVin(extracted.vin) ? `VIN ${laximo.normalizeVin(extracted.vin)}` : '');
  const parts = Array.isArray(extracted.partKeywords) ? extracted.partKeywords.filter(Boolean).slice(0, 4).join(', ') : '';
  const what = [parts || (extracted.vendorCode ? `деталь ${extracted.vendorCode}` : ''), car].filter(Boolean).join(' — ');
  return what ? `Понял запрос: ${what}` : null;
}

// ─── Turn record for the admin «Диалоги» tab (lib/chatTurns.js, 04.11) ──────
// The catalog trace of one message = its own [laximo]/[catalog]/[chat]/[extract]/DIAG
// log lines: console.log is wrapped once, and lines are collected only inside a
// running chat message (AsyncLocalStorage), so nothing else changes.
const turnStore = new AsyncLocalStorage();
const TRACE_RE = /^(\[(laximo|laximo-api|catalog|chat|extract|prices|manager|abcp|answer)\]|DIAG )/;
for (const level of ['log', 'warn', 'error']) {
  const orig = console[level].bind(console);
  console[level] = (...args) => {
    orig(...args);
    const t = turnStore.getStore();
    if (!t || t.trace.length >= 80) return;
    const line = args.map(a => (typeof a === 'string' ? a : JSON.stringify(a))).join(' ');
    if (TRACE_RE.test(line)) t.trace.push(line.slice(0, 1500));
  };
}
function noteTurn(key, value) { const t = turnStore.getStore(); if (t) t[key] = value; }

async function handler(req, res) {
  const calls = [];
  const started = Date.now();
  const stream = req.method === 'POST' && req.body && req.body.stream === true ? streamResponse(res) : null;
  const turn = { trace: [], status: 200, body: null };
  if (req.method === 'POST') {
    // Capture the final reply whatever exit it takes (plain JSON or the stream's last line).
    const status = res.status.bind(res), json = res.json.bind(res);
    res.status = c => { turn.status = c; status(c); return res; };
    res.json = body => { turn.body = body; return json(body); };
  }
  try {
    const work = () => usageStore.run(calls, () => handleChat(req, res));
    return await turnStore.run(turn, () => (stream ? progress.run(stream.emit, work) : work()));
  } finally {
    logUsage(calls);
    if (req.method === 'POST') {
      console.log(`[timing] message total: ${Date.now() - started} ms`);
      const msgs = Array.isArray(req.body && req.body.messages) ? req.body.messages : [];
      const lastUser = [...msgs].reverse().find(m => m && m.role === 'user');
      if (lastUser && turn.body) {
        chatTurns.record({
          convId: req.body.conv_id, sessionId: req.body.session_id,
          userText: pii.redactText(String(lastUser.content || '')),
          reply: turn.body.reply || '', error: turn.body.error || null,
          understood: turn.understood || null, trace: turn.trace,
          status: turn.status, ms: Date.now() - started,
        }).catch(() => {});
      }
    }
  }
}

async function handleChat(req, res) {
  const headers = corsHeaders();

  if (req.method === 'OPTIONS') {
    Object.entries(headers).forEach(([k, v]) => res.setHeader(k, v));
    return res.status(204).end();
  }

  if (req.method === 'GET') {
    Object.entries(headers).forEach(([k, v]) => res.setHeader(k, v));
    return res.status(200).json({ status: 'ok' });
  }

  if (req.method !== 'POST') {
    Object.entries(headers).forEach(([k, v]) => res.setHeader(k, v));
    return res.status(405).json({ error: 'Method not allowed' });
  }

  if (!LLM_API_KEY) {
    Object.entries(headers).forEach(([k, v]) => res.setHeader(k, v));
    return res.status(500).json({ error: 'API key not configured' });
  }

  try {
    const rawMessages = req.body.messages;
    if (!rawMessages || !Array.isArray(rawMessages)) {
      Object.entries(headers).forEach(([k, v]) => res.setHeader(k, v));
      return res.status(400).json({ error: 'messages array required' });
    }
    // Personal data stays on our server (152-ФЗ): every phone/email the
    // customer typed is masked before ANY LLM call -- request reading,
    // filters, the final answer all work on `messages`. The real values are
    // read here in code only, for the ABCP order check and to open the
    // request form (see lib/pii.js).
    const messages = pii.redactMessages(rawMessages);
    const typedContacts = pii.latestContacts(rawMessages);

    // (The whole price list is no longer downloaded here: products are looked
    // up by part number further down -- see lookupCatalog().)

    // Deterministic matching layer (see functions above) -- extract vehicle
    // fields cheaply, match them in plain JS, and only send Claude the
    // already-matched result instead of the full dataset.
    progress.step('Читаю ваш вопрос…');
    const extracted = await extractVehicleInfo(messages);
    noteTurn('understood', {
      car: [extracted.brand, extracted.model, extracted.engineCode].filter(Boolean).join(' ') || null,
      vin: extracted.vin || null, parts: extracted.partKeywords || null, number: extracted.vendorCode || null,
      orderStatus: extracted.orderStatusQuestion === true || extracted.orderStatusQuestion === 'true' || undefined,
    });
    // The LLM only saw masks, so contacts come from the code, not from it.
    extracted.contactPhone = typedContacts.phone;
    extracted.contactEmail = typedContacts.email;
    sanitizeContactPhone(extracted);
    dropInventedQualifiers(extracted, messages); // «Глушитель» must not become «задний глушитель» (live 28.10)
    dropGenericKeywords(extracted); // «колесный диск» + «диск» -> brake / CD discs (Диалоги ✗ 09.11)
    // «Датчик абсолютного давления и температуры воздуха» is ONE part (BMW «Датчик T-Map», owner
    // 09.11): the request reading split it into 4 sensor keywords -> 14 sensors (#326).
    if (TMAP_ASK.test(lastUserMessage(messages) || '') && Array.isArray(extracted.partKeywords) && extracted.partKeywords.length > 1) {
      const kw = 'датчик абсолютного давления и температуры воздуха';
      console.log(`[extract] T-Map sensor: ${extracted.partKeywords.join(', ')} -> «${kw}»`);
      extracted.partKeywords = [kw];
      extracted.partSearchNames = { [kw]: ['датчик t-map', 't-map'] };
      extracted.partGroups = { [kw]: ['13'] };
    }
    // Keys / coding = workshop services: no catalog work at all (see workshopServiceTopic).
    const workshopTopic = extracted.orderStatusQuestion === true || extracted.orderStatusQuestion === 'true' ? null : workshopServiceTopic(messages);
    if (workshopTopic) {
      console.log(`[service] workshop topic "${workshopTopic}": no part search (keywords were ${JSON.stringify(extracted.partKeywords)})`);
      extracted.partKeywords = null;
      extracted.vendorCode = null;
    }
    progress.step(understoodStep(extracted, workshopTopic));
    console.log("========== VEHICLE ==========");
console.log(JSON.stringify(extracted, null, 2));

    // ─── VIN PATH (Laximo / original BMW catalog) ─────────────────────────
    // If the customer gave a VIN, resolve the exact car and its OEM numbers
    // for the requested parts from the original catalog. When this yields
    // parts, it REPLACES the compatibility-table matching below; otherwise
    // (no VIN, VIN not found, no part named yet, scraper failed or slow)
    // we fall through to the table path exactly as before.
    // Questions about an existing order: answered from ABCP, no catalog work.
    if (extracted.orderStatusQuestion === true || extracted.orderStatusQuestion === 'true') {
      const ip = (req.headers['x-forwarded-for'] || req.socket?.remoteAddress || '').split(',')[0].trim();
      progress.step('Проверяю статус заказа…');
      let reply = await orderStatusReply(extracted, ip);
      // «Писал в телеграм - нет ответа» (Диалоги ✗ 05.11): the reply ended with
      // «напишите нам в Telegram или MAX» -- exactly what didn't work for them.
      if (NO_ANSWER_RE.test(lastUserMessage(messages) || '')) {
        reply = reply.replace(/\n*Если нужны подробности по срокам[^\n]*$/, '') +
          '\n\nИзвините, что вам не ответили. Оставьте контакты в короткой форме — менеджер свяжется с вами сам.\n<<<MANAGER_BUTTON>>>\n<<<CONTACT_FORM>>>';
        console.log('[order] the customer got no answer elsewhere -- request form instead of «write to Telegram»');
      }
      Object.entries(headers).forEach(([k, v]) => res.setHeader(k, v));
      res.setHeader('Content-Type', 'application/json');
      return res.status(200).json({ reply });
    }

    // The customer asks for a person (manager / operator / call me back):
    // escalate in code, before any part search. Live 03.11: «Связаться с
    // менеджером» and «Хочу уточнить у менеджера сроком доставки» went into the
    // catalog search, which answered with its own variant / generation
    // questions and returned before the AI could escalate.
    if (asksForPerson(lastUserMessage(messages))) {
      console.log('[manager] the customer asks for a person -- request form');
      const reply = 'Передам ваш вопрос менеджеру. Заполните, пожалуйста, короткую форму — описание вопроса уже подготовлено, укажите имя и телефон или email. Менеджер свяжется с вами в ближайшее время.\n<<<MANAGER_BUTTON>>>\n<<<CONTACT_FORM>>>';
      Object.entries(headers).forEach(([k, v]) => res.setHeader(k, v));
      res.setHeader('Content-Type', 'application/json');
      return res.status(200).json({ reply });
    }

    // «Это она?» follow-ups (owner 09.11): «Да» / «Нет, другая позиция» / a position number.
    {
      const reply = await confirmFollowUp(messages);
      if (reply) {
        Object.entries(headers).forEach(([k, v]) => res.setHeader(k, v));
        res.setHeader('Content-Type', 'application/json');
        return res.status(200).json({ reply });
      }
    }

    // A non-BMW article typed alone («CS010502PN», Диалоги ✗ 06.11): the site's
    // own search (ABCP) -> brand, name, cheapest offer. BMW / MINI numbers keep
    // their catalog path below.
    {
      const found = articleInMessage(lastUserMessage(messages), extracted);
      const art = found && found.code, brandHint = found && found.brandHint;
      if (art) {
        progress.step(`Ищу артикул ${art} у поставщиков…`);
        const codeOnly = !brandHint && String(lastUserMessage(messages) || '').replace(/[^A-Za-zА-Яа-яЁё0-9]/g, '').length <= art.length + 8;
        const reply = await articleLookupReply(art, (extracted.brand || '').toUpperCase(), codeOnly, brandHint);
        if (reply) {
          Object.entries(headers).forEach(([k, v]) => res.setHeader(k, v));
          res.setHeader('Content-Type', 'application/json');
          return res.status(200).json({ reply });
        }
      }
    }

    // Part number + car known -> check that number against the car's catalog.
    let compat = null;
    let compatSkipCode = null;
    // Safety net: the extraction step sometimes misses the part number when a
    // VIN is in the same message (seen 23.10: "Подойдёт 13628582663? VIN …").
    // Take an 11-digit number from the latest message (BMW format; spaces ok),
    // never the VIN or a phone number (7…/8… with 11 digits, or the extracted phone).
    // Also when the "part number" it returned is really the VIN, or isn't in
    // the customer's recent messages at all (seen 23.10: no check ran for
    // "Подойдёт 13627823945? VIN X4XZW61140L560928").
    {
      const norm = v => String(v || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
      const vc = norm(extracted.vendorCode);
      const recent = (messages || []).filter(m => m.role === 'user').slice(-2)
        .map(m => String(typeof m.content === 'string' ? m.content : '')).join(' ').toUpperCase().replace(/[\s\-.]/g, '');
      if (vc && (vc === norm(extracted.vin) || vc.length === 17)) {
        console.log(`[compat] extracted vendorCode "${extracted.vendorCode}" is the VIN -- ignored`);
        extracted.vendorCode = null;                 // wrong anyway
      } else if (vc && !recent.includes(vc)) {
        compatSkipCode = vc;                         // older number: keep it, just don't re-check it
      }
    }
    if (!extracted.vendorCode || compatSkipCode) {
      const last = [...(messages || [])].reverse().find(m => m.role === 'user');
      const text = String(last && typeof last.content === 'string' ? last.content : '').replace(/(\d)[\s-](?=\d)/g, '$1');
      const phone = String(extracted.contactPhone || '').replace(/\D/g, '').slice(-10);
      const found = (text.match(/(?<![\dA-Z])\d{11}(?![\dA-Z])/gi) || [])
        .find(n => !/^[78]9/.test(n) && !(phone && n.endsWith(phone)) && !String(extracted.vin || '').includes(n));
      if (found) { extracted.vendorCode = found; compatSkipCode = null; console.log(`[compat] part number ${found} taken from the message (missed by extraction)`); }
    }
    const compatCode = compatSkipCode ? '' : String(extracted.vendorCode || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
    // Only while the number is current: typed in one of the customer's last 2 messages.
    const recentUserText = (messages || []).filter(m => m.role === 'user').slice(-2)
      .map(m => String(typeof m.content === 'string' ? m.content : '')).join(' ').toUpperCase().replace(/[\s\-.]/g, '');
    if (compatCode.length >= 5 && recentUserText.includes(compatCode) && compatCode !== String(extracted.vin || '').toUpperCase()
        && (laximo.normalizeVin(extracted.vin) || (extracted.brand && extracted.model))) {
      compat = { code: compatCode, partName: null, source: 'customer' };
      if (!Array.isArray(extracted.partKeywords) || !extracted.partKeywords.length) {
        progress.step(`Проверяю номер детали ${compatCode}`);
        const info = await abcpPartName(compatCode, extracted.brand || 'BMW');
        if (info) Object.assign(compat, { partName: info.name, partBrand: info.brand, aftermarket: info.aftermarket, source: 'abcp' });
        if (info && info.name && !/[а-яё]/i.test(info.name)) {
          // English name from ABCP -> Russian, as the catalog names it.
          const ru = await toRussianPartName(info.name);
          console.log(`[compat] ABCP name "${info.name}" -> "${ru || '?'}"`);
          if (ru) { compat.partNameOriginal = info.name; info.name = ru; compat.partName = ru; }
        }
        const kw = keywordsFromName(info && info.name);
        if (kw.length) extracted.partKeywords = kw; // drives the Laximo name search below
      }
      if (!extracted.partKeywords || !extracted.partKeywords.length) compat.verdict = 'no_part_name';
    }

    const laximoOutcome = {};
    const laximoResult = workshopTopic ? null : await lookupLaximo(extracted, messages, laximoOutcome);
    // Dashboard «Подбор» (green / red dot per chat): the outcome goes back with
    // the reply and the widget logs it -- the chat session is created only
    // after the first reply, so the server doesn't know it yet. No outcome =
    // the catalog wasn't needed for this message (white dot).
    const catalogOutcome = laximoOutcome.mode ? { status: ['ok', 'empty'].includes(laximoOutcome.status) ? laximoOutcome.status : 'blocked',
      reason: laximoOutcome.reason || (laximoOutcome.status ? null : 'нет результата'), mode: laximoOutcome.mode, vehicle: laximoOutcome.vehicle || null } : null;
    if (compat && !compat.verdict) Object.assign(compat, compatVerdict(compat.code, laximoResult));
    // Laximo couldn't check (site block, pause, disabled): fall back to our
    // compatibility table when the model is known; with only a VIN, ask for
    // the model (a VIN can't be decoded without Laximo).
    if (compat && ['unavailable', 'no_part_name'].includes(compat.verdict)) {
      compat.catalogUnavailable = true;
      // The car may be known from a saved VIN lookup even when the part search
      // is blocked (seen 23.10: "X5 40dX", Код модели E70N) -> use it for the
      // table: series + body code ("X5 E70"), no trim (tables spell it differently).
      let car = extracted.brand && extracted.model ? { brand: extracted.brand, model: extracted.model } : null;
      const lv = laximoResult && laximoResult.vehicle;
      if (!car && lv && lv.name) {
        const series = String(lv.name).trim().split(/\s+/)[0];
        const body = String((lv.options && (lv.options['Код модели'] || lv.options['Серия'])) || '').trim().match(/^[A-Z]\d{2,3}/i);
        if (series) car = { brand: lv.brand || 'BMW', model: [series, body && body[0].toUpperCase()].filter(Boolean).join(' ') };
        if (car) compat.carFromVin = `${car.brand} ${car.model}`;
      }
      if (car) {
        const recs = await fetchCompatibilityByVendorCode(compat.code);
        const fits = (matchCompatibility({ [compat.code]: recs }, { ...extracted, ...car, vendorCode: null })[compat.code]) || [];
        const desc = r => [r.brand, r.model, r.modificationName, r.engineCode,
          r.years || [r.yearFrom, r.yearTo].filter(Boolean).join('–')].filter(Boolean).join(' ');
        if (fits.length) Object.assign(compat, { verdict: 'table_fits', tableVehicles: fits.slice(0, 5).map(desc) });
        else if (recs.length) Object.assign(compat, { verdict: 'table_other_vehicles', tableVehicles: [...new Set(recs.map(desc))].slice(0, 8) });
        else compat.verdict = 'table_no_data';
      } else if (laximo.normalizeVin(extracted.vin)) {
        compat.verdict = 'vin_unavailable_need_model';
      }
    }
    if (compat) console.log('DIAG compat', JSON.stringify({ code: compat.code, source: compat.source, partName: compat.partName, keywords: extracted.partKeywords, aftermarket: compat.aftermarket || false, verdict: compat.verdict, tableRows: compat.tableVehicles ? compat.tableVehicles.length : undefined, by: laximoResult?.matchedBy || null }));

    // Model path couldn't decide a dropdown (e.g. "M240i" -> B58C or B58D?).
    // Ask the customer directly with the catalog's own options as buttons --
    // their click comes back as text the wizard can match on the next turn.
    // Cheap: no Sonnet call, no catalog payload.
    // Clarifying question from the AI filter: the catalog has several
    // different parts for a vague request -- the customer picks, and the next
    // message gets exactly that part (results are cached: no new catalog requests).
    if (laximoResult?.clarify) {
      const { question, options } = laximoResult.clarify;
      const v = laximoResult.vehicle;
      const car = v && v.name ? ` для вашего ${v.brand || 'BMW'} ${v.name}` : '';
      // The AI's own question line is not shown (live 28.10: «Какую деталь вам нужна?») -- the fixed lead already asks.
      const isVersion = laximoResult.clarify.lead === VARIANT_LEAD;
      const isAxle = laximoResult.clarify.lead === AXLE_LEAD;
      const isEquip = laximoResult.clarify.lead === EQUIP_LEAD;
      const isSide = laximoResult.clarify.lead === SIDE_LEAD;
      const reply = (isVersion
        ? `${VARIANT_LEAD}. ${question}\n\nЕсли не знаете -- нажмите «${VARIANT_UNKNOWN}»: покажу все варианты, а менеджер уточнит по VIN.`
        : isEquip
          ? `${EQUIP_LEAD}${car}. Есть ли у вашего автомобиля «${question}»?\n\nЕсли не знаете — нажмите «${EQUIP_UNKNOWN}»: покажу все варианты, а по VIN подберу точно.`
        : isAxle
          ? `${question}${car}? Выберите ниже:`
        : isSide
          ? `${SIDE_LEAD}${car}: левая, правая или обе? Выберите ниже:`
          : `${CLARIFY_LEAD}: по оригинальному каталогу${car} есть несколько вариантов. Выберите ниже:`) +
        `\n<<<BUTTONS>>>\n${JSON.stringify([...options.map(o => o.label), laximoResult.clarify.allLabel || CLARIFY_ALL])}\n<<<END_BUTTONS>>>`;
      console.log('DIAG laximo-clarify', JSON.stringify({ question, options }));
      Object.entries(headers).forEach(([k, v2]) => res.setHeader(k, v2));
      res.setHeader('Content-Type', 'application/json');
      return res.status(200).json({ reply, ...(catalogOutcome ? { catalog: catalogOutcome } : {}) });
    }
    if (laximoResult?.needsChoice) {
      const { step, options } = laximoResult.needsChoice;
      const what = WIZARD_STEP_QUESTIONS[step] || String(step).toLowerCase();
      const buttons = options.slice(0, 32); // 30.10: the 5 Series has ~23 generations/LCI in Laximo; 16 cut off the newest (G30 LCI … G61)
      // Same question again (live 29.10: the customer re-sent «X5 G05 LCI» instead of a
      // modification): say what is already known and what is still missing, not the same text.
      const prev = String(([...(messages || [])].reverse().find(m => m.role === 'assistant') || {}).content || '');
      const again = prev.includes(`уточните, пожалуйста, ${what}`);
      const known = laximoResult.needsChoice.chosen && laximoResult.needsChoice.chosen.length ? ` (${laximoResult.needsChoice.chosen.join(', ')} — уже учтено)` : '';
      const reply = (again
        ? `Для точного подбора осталось выбрать ${what}${known} — нажмите нужную кнопку ниже.`
        : `Чтобы подобрать детали по оригинальному каталогу производителя, уточните, пожалуйста, ${what}:`) +
        `\n\nЛибо пришлите VIN (17 символов, указан в СТС) — по нему подбор будет точнее.` +
        `\n<<<BUTTONS>>>\n${JSON.stringify(buttons)}\n<<<END_BUTTONS>>>`;
      console.log('DIAG laximo-needs-choice', JSON.stringify({ step, optionCount: options.length }));
      Object.entries(headers).forEach(([k, v]) => res.setHeader(k, v));
      res.setHeader('Content-Type', 'application/json');
      return res.status(200).json({ reply, ...(catalogOutcome ? { catalog: catalogOutcome } : {}) });
    }
    // Unsure catalog match (owner 09.11): the diagram with the marked part + «Это она?».
    if (laximoResult && !workshopTopic && !compat && !isServiceRequest(messages, extracted)) {
      const reply = await confirmQuestionIfUnsure(laximoResult, extracted, messages).catch(err => { console.error('[confirm] failed:', err.message); return null; });
      if (reply) {
        Object.entries(headers).forEach(([k, v]) => res.setHeader(k, v));
        res.setHeader('Content-Type', 'application/json');
        return res.status(200).json({ reply, ...(catalogOutcome ? { catalog: catalogOutcome } : {}) });
      }
    }
    let vinVehicleForPrompt = 'Нет данных (клиент не назвал VIN).';
    const laximoDownReason = !LAXIMO_ENABLED ? 'disabled' : await laximo.unavailableReason().catch(() => null);
    const givenVin = laximo.normalizeVin(extracted.vin);
    if (givenVin && !laximoResult) {
      vinVehicleForPrompt = `Клиент указал VIN ${givenVin}, но подбор по VIN сейчас недоступен. НЕ обещай подбор по VIN и не проси VIN повторно: предложи передать VIN менеджеру для точного подбора (кнопка менеджера) и подбирай по марке/модели/году, если клиент их назвал.`;
    }
    if (laximoDownReason && !laximoResult) {
      vinVehicleForPrompt += ` ВНИМАНИЕ: оригинальный каталог производителя СЕЙЧАС ВРЕМЕННО НЕДОСТУПЕН, проверить по нему не удалось. НЕ говори клиенту, что детали нет у производителя или "среди оригинальных номеров" — это неизвестно. Если в КАТАЛОГЕ ТОВАРОВ подходящего нет, скажи, что сейчас не удалось найти её автоматически, и предложи менеджера: он подберёт деталь по оригинальному каталогу (лучше всего по VIN) и проверит наличие и сроки.`;
    }
    if (laximoResult?.notFound) {
      vinVehicleForPrompt = `VIN ${laximoResult.vin} не найден в оригинальных каталогах производителей. Попроси клиента проверить VIN или назвать марку, модель и год.`;
    } else if (laximoResult?.vehicle && laximoResult.matchedBy === 'model') {
      const v = laximoResult.vehicle;
      vinVehicleForPrompt = JSON.stringify({
        matchedBy: 'model',
        note: 'Подобрано по модели, без VIN',
        brand: v.brand,
        catalogPath: (v.path || []).join(' › '),
        model: v.name, modelCode: v.modelCode, ...v.options,
      });
    } else if (laximoResult?.vehicle) {
      const v = laximoResult.vehicle;
      vinVehicleForPrompt = JSON.stringify({ matchedBy: 'vin', vin: laximoResult.vin, brand: v.brand, model: v.name, modelCode: v.modelCode, ...v.options });
    }
    if (laximoResult?.tires) {
      const t = laximoResult.tires;
      vinVehicleForPrompt += `\n\nШИНЫ ПО ОРИГИНАЛЬНОМУ КАТАЛОГУ: раздел «${t.category}» (${t.units.join(', ')}).` +
        (t.catalogSizes.length ? ` Оригинальные размеры для этой машины: ${t.catalogSizes.join(', ')}.` : '') +
        (t.sizeMissing
          ? ` Размера ${t.sizeMissing}, который назвал клиент, в оригинальном каталоге для этой машины НЕТ — скажи это одной фразой, назови оригинальные размеры и покажи карточки; предложи менеджера, если нужен именно этот размер (он подскажет, подходит ли он по допускам).`
          : t.asked.length ? ` Карточки ниже — шины размера ${t.asked.join(', ')}.` : ' Если размеров несколько, а клиент не назвал свой, спроси размер (он на боковине шины или на наклейке в проёме водительской двери).');
    }
    const laximoUsed = !!(laximoResult?.parts && laximoResult.parts.length);
    // Laximo is the ONLY source of what fits the car (owner 30.10). The client's
    // compatibility table is used in one case only: Laximo can't be reached --
    // ABCP's browser check paused it (or the hourly budget / circuit breaker that
    // protect against that block), or it is switched off (LAXIMO_ENABLED=false).
    // Otherwise (car not identified yet, no parts found, catalog too slow) the
    // customer is asked for VIN / model, or told to retry -- never offered parts
    // from the table.
    const laximoBlockedReason = laximoDownReason || laximoResult?.unavailable
      || (laximo.breakerOpen('core') ? "circuit breaker 'core' open" : null)
      || (laximoResult?.searchFailed && !laximoUsed ? 'search interrupted (pause / block)' : null);
    // Second exception (owner 30.10): «на какие машины подходит 34116864906?» --
    // a part number with no identified car. Laximo can't search from a number to
    // cars, the compatibility table can.
    const articleOnlyQuestion = !laximoUsed && !!extracted.vendorCode && !laximoResult?.vehicle && !laximo.normalizeVin(extracted.vin);
    if (!laximoUsed) {
      if (laximoBlockedReason) {
        console.log(`[catalog] Laximo blocked (${laximoBlockedReason}) -- compatibility table used`);
        // only when a part / car was asked about (not for «Привет»)
        if ((extracted.partKeywords || []).length || extracted.vendorCode || laximo.normalizeVin(extracted.vin)) {
          progress.step('Оригинальный каталог сейчас недоступен — смотрю нашу таблицу совместимости');
        }
      } else if (articleOnlyQuestion) {
        console.log(`[catalog] part number ${extracted.vendorCode} without an identified car -- compatibility table used for «which cars does it fit»`);
      } else {
        const timedOut = laximoOutcome.status === 'blocked' && /тайм-аут/.test(laximoOutcome.reason || '');
        console.log(`[catalog] compatibility table NOT used (Laximo only): ${timedOut ? 'catalog timeout' : laximoResult?.vehicle ? 'no parts found for the car' : 'car not identified in the catalog yet'}`);
        vinVehicleForPrompt += timedOut
          ? ' ВНИМАНИЕ: оригинальный каталог сейчас не ответил вовремя. Детали и артикулы НЕ предлагай: коротко извинись и попроси повторить запрос через минуту (или прислать VIN).'
          : laximoResult?.vehicle
            ? ' По оригинальному каталогу для этого автомобиля по запросу ничего не найдено. Детали из других источников НЕ предлагай: попроси уточнить название детали (как она называется или для чего) или предложи менеджера.'
            : ' Автомобиль клиента по оригинальному каталогу ещё НЕ определён. Детали подбираются ТОЛЬКО по оригинальному каталогу: НЕ предлагай детали, артикулы и цены, а попроси VIN (лучше всего) или марку, модель, кузов и двигатель.';
      }
    }

    let matchedCompatibilityByVehicle;
    let matchedCatalogByVehicle;

    if (laximoUsed) {
      progress.step('Проверяю, что есть в нашем магазине');
      const catalogIndex = await lookupCatalog(laximoResult.parts.map(p => p.oem), catalogBrand(extracted, laximoResult));
      const v = laximoResult.vehicle;
      matchedCompatibilityByVehicle = {};
      for (const p of laximoResult.parts) {
        const record = {
          source:    'laximo',
          matchedBy: laximoResult.matchedBy, // 'vin' = exact car; 'model' = by model, no VIN
          brand:     v.brand || 'BMW',
          vin:       laximoResult.vin || null,
          model:     v.name,
          chassis:   v.options?.['Код модели'] || null,
          engine:    v.options?.['Двигатель'] || null,
          productionDate: v.options?.['Дата выпуска'] || null,
          partName:  p.name,
          query:     p.query || null, // which of the customer's parts this row answers (06.11)
          ...(p.fixedName ? { isAskedPart: `да — это и есть «${p.fixedName}» (так в каталоге BMW называется эта деталь)` } : {}),
          axle:      p.axle || null, // передняя / задняя ось -- from the BMW number (31/33, 34 1x/2x)
          variant:   p.alternative ? 'альтернатива (оригинальная принадлежность BMW)' : (p.kitWithSensor ? 'комплект с датчиком износа' : null),
          condition: p.condition || null, // e.g. «Спортивные тормоза M (S2NHA) = нет» (group search)
          equipmentAnswer: laximoResult.parts.equipmentAnswer ? `${laximoResult.parts.equipmentAnswer.label}: ${laximoResult.parts.equipmentAnswer.answer === 'unknown' ? 'клиент не знает' : laximoResult.parts.equipmentAnswer.answer}` : null,
          unit:      p.unit,
          position:  p.position,
          qty:       p.qty,
          notes:     Object.fromEntries(Object.entries(p.notes || {}).filter(([k]) => k !== 'Количество')),
        };
        (matchedCompatibilityByVehicle[p.oem] ||= []).push(record);
      }
      // Laximo returns normalized OEMs; catalog articles are looked up the
      // same way, then keyed back by the catalog's own article string so the
      // rest of the handler (missing-articles logging, prompt) is unchanged.
      matchedCatalogByVehicle = [];
      const remapped = {};
      for (const [oem, records] of Object.entries(matchedCompatibilityByVehicle)) {
        const product = catalogIndex.get(oem);
        if (product) {
          matchedCatalogByVehicle.push(product);
          remapped[product.article] = records;
        } else {
          remapped[oem] = records;
        }
      }
      matchedCompatibilityByVehicle = remapped;
    } else if (!laximoBlockedReason && !articleOnlyQuestion) {
      // Laximo only (see laximoBlockedReason / articleOnlyQuestion): no parts from the compatibility table.
      matchedCompatibilityByVehicle = {};
      matchedCatalogByVehicle = [];
    } else {

    // Now that we know the vehicle's series, pull just that series' rows
    // instead of the whole compatibility table.
    const series = extractSeries(extracted.model);
    let compatibilityData = await fetchCompatibilityBySeries(series);

    // If the customer named a specific vendorCode, make sure ITS
    // compatibility rows are available regardless of whether the series
    // lookup above found anything -- e.g. no brand/model was ever
    // mentioned (series === 'unknown', fetchCompatibilityBySeries returns
    // {}), or the part's series differs from whatever vehicle info was
    // extracted. Without this, a pure "what car does 61319483006 fit?"
    // question with no stated vehicle silently gets no compatibility data
    // at all, even though matchCompatibility() below is fully able to
    // answer from the vendorCode alone. Skipped when the series fetch
    // already has this code, to avoid a redundant DB round-trip on the
    // common case (customer gave both a vehicle and a part number).
    if (extracted.vendorCode && !compatibilityData[extracted.vendorCode]) {
      const directVehicles = await fetchCompatibilityByVendorCode(extracted.vendorCode);
      if (directVehicles.length) {
        compatibilityData = { ...compatibilityData, [extracted.vendorCode]: directVehicles };
      }
      // TEMPORARY DIAGNOSTIC LOGGING -- confirms this path actually fires
      // in production and how often the direct fetch finds something the
      // series fetch missed (e.g. no vehicle mentioned at all, or a
      // cross-series part). Same style as the existing DIAG match-check
      // block further down.
      console.log('DIAG vendor-code-direct-compat', JSON.stringify({
        vendorCode: extracted.vendorCode,
        series,
        seriesHadIt: false, // guaranteed false here -- we only reach this branch when it didn't
        directHitCount: directVehicles.length,
      }));
    }

    matchedCompatibilityByVehicle = matchCompatibility(compatibilityData, extracted);
    const vendorCodesMatched = new Set(Object.keys(matchedCompatibilityByVehicle));
    const foundInList = await lookupCatalog([...vendorCodesMatched], catalogBrand(extracted, laximoResult));
    matchedCatalogByVehicle = [...vendorCodesMatched]
      .map(code => { const p = foundInList.get(laximo.normalizeOem(code)); return p ? { ...p, article: code } : null; })
      .filter(Boolean);
    } // end compatibility-table path (non-VIN)

    const matchedVendorCodesByVehicle = new Set(Object.keys(matchedCompatibilityByVehicle));

    // Parts that genuinely fit this vehicle (per the compatibility data)
    // but have no entry at all in catalogParsed -- almost always because
    // ABCP's export excludes items without a photo (see README's
    // "Compatibility matching architecture" -- the catalog feed is
    // configured upstream to only include items with images, precisely so
    // the agent never recommends something with no visual). Rather than
    // just silently having nothing to offer, log these so the client can
    // see which specific parts are blocking a sale and go add a photo for
    // them. Fire-and-forget -- must never block or fail the chat response.
    const missingVendorCodes = [...matchedVendorCodesByVehicle].filter(
      code => !matchedCatalogByVehicle.some(p => p.article === code)
    );
    // VIN path: OEM numbers the original catalog found for this exact car
    // but that aren't in the catalog feed. Instead of the agent only saying
    // "not found", it gives the customer the exact BMW part number and
    // offers a manager to check availability/order by that number (the
    // client sells original parts and can usually order them). Capped so a
    // broad search can't flood the prompt.
    const MAX_LAXIMO_NOT_IN_CATALOG = 15;
    // ТО request: service parts only (see NON_SERVICE_PART_RE).
    const serviceRequest = isServiceRequest(messages, extracted);
    const serviceOnly = serviceRequest && !asksForNonServicePart(messages);
    const laximoNameOf = code => ((matchedCompatibilityByVehicle[code] || [])[0] || {}).partName || null;
    const laximoNotInCatalog = laximoUsed
      ? missingVendorCodes.filter(code => !(serviceOnly && isNonServicePart(laximoNameOf(code))))
          .slice(0, MAX_LAXIMO_NOT_IN_CATALOG).map(code => {
          const r = (matchedCompatibilityByVehicle[code] || [])[0] || {};
          return {
            oem: code,
            name: r.partName || null,
            ...(r.unit ? { unit: r.unit } : {}),
            ...(r.notes && Object.keys(r.notes).length ? { notes: r.notes } : {}),
          };
        })
      : [];

    if (missingVendorCodes.length) {
      logMissingArticles(missingVendorCodes, extracted).catch(err =>
        // Node's top-level "fetch failed" message hides the real cause
        // (DNS, TLS, connection refused, timeout...) -- err.cause carries
        // the underlying error. Also log whether SUPABASE_URL looks sane,
        // since a wrong/missing env var in THIS deployment's environment
        // scope (e.g. set for Production but this is a Preview deploy)
        // would produce this exact generic failure with no other clue.
        console.error(
          'logMissingArticles error:', err.message, err.cause || '',
          '| SUPABASE_URL set:', !!SUPABASE_URL, '| SUPABASE_SERVICE_KEY set:', !!SUPABASE_SERVICE_KEY
        )
      );
    }

    // Narrow the vehicle-matched slice down to the part actually being asked
    // about (see filterCatalogByPartKeyword above) -- this is what keeps
    // prompt size scoped to the question rather than to total catalog size.
    // Safety net: if the customer hasn't named a part yet (partKeyword is
    // null -- e.g. still in the middle of the "which car do you have"
    // back-and-forth), fall back to a hard cap instead of sending every
    // part that ever fits their vehicle.
    const MAX_UNFILTERED_CATALOG_ITEMS = 40;
    let matchedCatalog;
    let partFilterApplied = false;
    if (laximoUsed) {
      // Laximo results already come from a part-NAME search for exactly
      // these keywords, so a second keyword filter would only drop real
      // matches whose catalog names are worded differently. Just cap it.
      matchedCatalog = matchedCatalogByVehicle.slice(0, MAX_UNFILTERED_CATALOG_ITEMS);
    } else if (extracted.partKeywords && extracted.partKeywords.length) {
      matchedCatalog = filterCatalogByPartKeyword(matchedCatalogByVehicle, extracted.partKeywords);
      partFilterApplied = true;
      // Safety net: an imperfect extraction shouldn't turn a real result
      // into a false "nothing found" -- fall back to the capped unfiltered
      // set rather than silently returning empty.
      if (matchedCatalog.length === 0 && matchedCatalogByVehicle.length > 0) {
        matchedCatalog = matchedCatalogByVehicle.slice(0, MAX_UNFILTERED_CATALOG_ITEMS);
        partFilterApplied = false;
      }
    } else if (matchedCatalogByVehicle.length > MAX_UNFILTERED_CATALOG_ITEMS) {
      matchedCatalog = matchedCatalogByVehicle.slice(0, MAX_UNFILTERED_CATALOG_ITEMS);
    } else {
      matchedCatalog = matchedCatalogByVehicle;
    }
    if (workshopTopic) matchedCatalog = []; // keys / coding: no product cards
    if (serviceOnly) {
      const dropped = matchedCatalog.filter(p => isNonServicePart(p.name, p.category, laximoNameOf(p.article)));
      if (dropped.length) {
        matchedCatalog = matchedCatalog.filter(p => !dropped.includes(p));
        console.log(`[service] ТО request: ${dropped.length} non-service part(s) left out: ${dropped.map(p => `${p.article} (${p.name})`).join(', ')}`);
      }
    }

    const matchedVendorCodes = new Set(matchedCatalog.map(p => p.article));
    const matchedCompatibility = {};
    for (const code of matchedVendorCodes) {
      if (matchedCompatibilityByVehicle[code]) matchedCompatibility[code] = matchedCompatibilityByVehicle[code];
    }

    // The customer already said which generation (a button «G02» / «G02 LCI»,
    // or «X4 G02» typed): keep that generation's records and the parts that
    // fit it. Live 29.10: «G02» was asked again and again -- «G02» is also
    // inside «G02 LCI», and the answer was never used. Exact match per
    // message, so «G02» never counts as «G02 LCI» (and the other way round).
    const chosenGeneration = generationAnswer(messages, detectGenerationAmbiguity(matchedCompatibility).map(g => g.generation));
    if (chosenGeneration) {
      const kept = {};
      for (const [code, hits] of Object.entries(matchedCompatibility)) {
        const fit = hits.filter(r => extractGeneration(r.model) === chosenGeneration);
        if (fit.length) kept[code] = fit;
      }
      if (Object.keys(kept).length) {
        for (const code of Object.keys(matchedCompatibility)) if (!kept[code]) delete matchedCompatibility[code];
        Object.assign(matchedCompatibility, kept);
        matchedCatalog = matchedCatalog.filter(p => matchedCompatibility[p.article] || !matchedCompatibilityByVehicle[p.article]);
        console.log(`[generation] customer chose "${chosenGeneration}": ${Object.keys(kept).length} code(s) kept`);
      }
    }

    const compatibility = JSON.stringify(matchedCompatibility);
    const catalogForPrompt = JSON.stringify(matchedCatalog);

    // ─── COST SHORT-CIRCUIT: generation ambiguity ───────────────────────────
    // If the customer named a part and a model, but hasn't given a year or
    // engine code, AND the matched vendorCodes span more than one distinct
    // generation of that model (e.g. BMW X5's E70/F15/G05), the main agent
    // can never confidently recommend a product this turn -- the ONLY
    // useful thing it can do is ask which generation the customer has.
    // Previously that still went through the full path: entire matched
    // catalog + compatibility blob (all generations at once) sent to
    // Sonnet 5, just to conclude "please tell me your year" -- confirmed
    // real incident, $0.38 for a single clarifying question with zero
    // products shown. Short-circuit here instead: skip Sonnet and the
    // catalog/compatibility payload entirely, ask a cheap Haiku call to
    // phrase the clarifying question using ONLY the small list of detected
    // generations (a few dozen tokens, not the full matched dataset).
    // (Never needed on the VIN path -- the VIN already pins the generation.)
    // Never the same generation question twice in a row: if the last reply
    // already offered these generations, the full answer path takes over.
    const lastReply = String(([...(messages || [])].reverse().find(m => m.role === 'assistant') || {}).content || '');
    const askedBefore = gens => gens.length > 1 && gens.every(g => lastReply.includes(g));
    if (!laximoResult?.vehicle && partFilterApplied && extracted.model && !extracted.year && !extracted.engineCode && !chosenGeneration
        && !askedBefore(detectGenerationAmbiguity(matchedCompatibility).map(g => g.generation))) {
      const generationOptions = detectGenerationAmbiguity(matchedCompatibility);
      if (generationOptions.length > 1) {
        const optionsForPrompt = generationOptions.slice(0, 6);
        console.log('DIAG generation-ambiguity-shortcut', JSON.stringify({
          brand: extracted.brand, model: extracted.model, partKeywords: extracted.partKeywords,
          generationCount: optionsForPrompt.length,
          skippedSonnetCall: true,
        }));

        const CLARIFY_PROMPT = `Ты — дружелюбный ИИ-консультант по автозапчастям BMW Club77, отвечаешь ТОЛЬКО по-русски, кратко и по делу.
Клиент ищет деталь "${(extracted.partKeywords || []).join(', ')}" для ${extracted.brand || ''} ${extracted.model || ''}, но для этой модели есть несколько поколений с разными деталями:
${optionsForPrompt.map(g => `- ${g.generation}${g.years ? ` (${g.years})` : ''}`).join('\n')}
Кратко объясни, что для точного подбора нужно уточнить поколение (код кузова) или год выпуска, и перечисли перечисленные варианты. Не здоровайся (это продолжение диалога). НЕ упоминай товары, цены или артикулы -- их в этом ответе быть не должно.`;

        try {
          progress.step('Формулирую уточняющий вопрос…');
          const clarifyRes = await fetch(`${LLM_BASE_URL}/v1/messages`, {
            method: 'POST',
            headers: {
              'Content-Type':      'application/json',
              'x-api-key':         LLM_API_KEY,
              'anthropic-version': '2023-06-01',
            },
            body: JSON.stringify({
              model:       LLM_MODEL, // room for thinking
              max_tokens:  4000,
              messages:    [{ role: 'user', content: CLARIFY_PROMPT }],
            }),
            signal: AbortSignal.timeout(30000),
          });

          if (clarifyRes.ok) {
            const clarifyData = await clarifyRes.json();
            trackUsage(LLM_MODEL, clarifyData);
            const clarifyBlock = (clarifyData.content || []).find(b => b.type === 'text');
            const clarifyText = (clarifyBlock?.text && stripHistoryPlaceholders(clarifyBlock.text))
              || `Для BMW ${extracted.model} есть несколько поколений с разными деталями. Уточните, пожалуйста, год выпуска или код кузова (${optionsForPrompt.map(g => g.generation).join(', ')}).`;

            const buttonLabels = optionsForPrompt.map(g => g.generation);
            const buttonsBlock = buttonLabels.length
              ? `\n<<<BUTTONS>>>\n${JSON.stringify(buttonLabels)}\n<<<END_BUTTONS>>>`
              : '';

            Object.entries(headers).forEach(([k, v]) => res.setHeader(k, v));
            res.setHeader('Content-Type', 'application/json');
            return res.status(200).json({ reply: clarifyText + buttonsBlock });
          }
          // Haiku call itself failed -- fall through to the normal full
          // path below rather than leaving the customer with no response.
        } catch (err) {
          console.error('generation-ambiguity clarify call failed, falling back to full path:', err.message);
          // fall through
        }
      }
    }

    // Manual-products matching, two independent paths merged together:
    // 1) Oil/fluid cross-sell (Tier 1: exact approval code match). Tier 2
    //    (general fuel/turbo/mileage fallback when the customer doesn't
    //    know their required approval) is not yet implemented -- this path
    //    contributes nothing in that case, and the prompt instructs the
    //    agent accordingly (see ПОДБОР МАСЛА skill below).
    // 2) Vehicle-fitment match, for manual_products that carry a `fitment`
    //    list (physical parts tied to specific car models -- see
    //    products.js). Independent of approval codes entirely.
    const oilProducts = await fetchOilProducts();
    const matchedByApproval = extracted.oilApprovalCode
      ? matchOilByApproval(oilProducts, extracted.oilApprovalCode)
      : [];
    const matchedByVehicleFitment = matchManualProductsByVehicle(oilProducts, extracted);
    // Merge + dedupe by id -- a product could in principle satisfy both
    // (an oil with an approval code AND a fitment list), don't send it twice.
    const matchedOilProductsMap = new Map();
    [...matchedByApproval, ...matchedByVehicleFitment].forEach(p => matchedOilProductsMap.set(p.id, p));
    const matchedOilProducts = [...matchedOilProductsMap.values()];
    const oilProductsForPrompt = JSON.stringify(matchedOilProducts);

    // TEMPORARY DIAGNOSTIC LOGGING — shows what the matching layer actually
    // found, plus payload size for cost comparison against the old
    // full-blob approach.
    console.log('DIAG match-check', JSON.stringify({
      source: laximoUsed ? 'laximo' : 'compatibility-table',
      laximoNotInCatalogCount: laximoNotInCatalog.length,
      partKeywords: extracted.partKeywords || null,
      partFilterApplied,
      vehicleMatchedCount: matchedCatalogByVehicle.length,
      finalMatchedCount: matchedCatalog.length,
      compatibilityPromptChars: compatibility.length,
      catalogPromptChars: catalogForPrompt.length,
      totalOilProducts: oilProducts.length,
      matchedOilProductCount: matchedOilProducts.length,
    }));

    // Part number typed by the customer IN THIS MESSAGE -> the widget shows a
    // button to the site's search page for it (all offers incl. "под заказ",
    // prices, delivery times -- also for parts with no card in the feed).
    const partLinkCodes = workshopTopic ? [] : partLinksForMessage(extracted, messages);
    const compatNote = compat ? `\n\n═══════════════════════════════════════════\nПРОВЕРКА СОВМЕСТИМОСТИ АРТИКУЛА (результат автоматической проверки по оригинальному каталогу — опирайся ТОЛЬКО на него):\n═══════════════════════════════════════════\n${JSON.stringify({ ...compat, matchedBy: laximoResult?.matchedBy || null, vehicle: laximoResult?.vehicle?.name || null })}\nПравила по полю "verdict":\n- "fits": номер ЕСТЬ в оригинальном каталоге для автомобиля клиента. Если matchedBy = "vin" — скажи, что совместимость подтверждена по VIN. Если "model" — что по каталогу номер подходит для этой модели, а для полной уверенности можно прислать VIN. Упомяни узел (unit) и условия из notes, если есть.\n- "other_numbers": номера клиента в каталоге его автомобиля НЕТ, но для этой детали каталог указывает другие номера (catalogNumbers). Скажи это прямо и вежливо, назови номера из каталога. Возможные причины: номер устарел/заменён, деталь для другой модификации. Если "aftermarket": true — номер клиента от другого производителя (аналог), а оригинальный номер для машины — из catalogNumbers; подходит ли аналог, уточнит менеджер. Предложи менеджера для окончательной проверки.\n- "part_not_found": по названию детали в каталоге автомобиля ничего не найдено — скажи, что автоматически проверить не удалось, предложи менеджера (<<<MANAGER_BUTTON>>>).\n- "vehicle_not_found": автомобиль по VIN не найден — попроси проверить VIN.\n- "unavailable" или "no_part_name": проверить автоматически сейчас не удалось — скажи это и предложи менеджера (<<<MANAGER_BUTTON>>>), НЕ утверждай, что деталь подходит или не подходит.
- "vin_unavailable_need_model": проверка по VIN в оригинальном каталоге СЕЙЧАС ВРЕМЕННО НЕДОСТУПНА. Скажи это коротко и попроси марку, модель с кодом кузова (например X5 F15), двигатель или год — по ним проверишь по базе совместимости. НЕ утверждай, подходит ли деталь.
- "table_fits": оригинальный каталог сейчас недоступен, но по НАШЕЙ БАЗЕ СОВМЕСТИМОСТИ номер указан для автомобиля клиента (tableVehicles). Если есть поле carFromVin — автомобиль уже определён по VIN, НЕ проси подтвердить модель, сразу дай результат. Скажи "по нашей базе совместимости подходит для …", назови запись(и) и добавь, что для 100% уверенности можно проверить по VIN позже или уточнить у менеджера.
- "table_other_vehicles": оригинальный каталог сейчас недоступен; в нашей базе совместимости этот номер указан ТОЛЬКО для других автомобилей (tableVehicles). Назови их и скажи, что для модели клиента подтверждения в базе нет — это не значит, что не подходит; предложи проверку менеджером (<<<MANAGER_BUTTON>>>) или по VIN позже.
- "table_no_data": оригинальный каталог сейчас недоступен, и в базе совместимости по номеру данных нет — скажи, что сейчас проверить не получается, предложи менеджера (<<<MANAGER_BUTTON>>>).\nНИКОГДА не утверждай совместимость сверх этого результата.` : '';
    // Original numbers found for the car but missing from the feed get the same
    // "Открыть деталь" button (the site's search page shows their offers,
    // prices and delivery times) -- up to 3, after a typed number.
    // (Not when the customer's own number was confirmed: then the other
    // results of the name search are different parts, not alternatives.)
    // ─── DIAGRAM CARDS (owner 30.10) ───────────────────────────────────────────
    // Parts that fit by the catalog but have no card in the price list (the
    // export only carries items WITH a photo -- they can still be in stock) get a
    // product card of their own in the same carousel: catalog name, axle, live
    // price and delivery, the site search link, and the BMW diagram as the
    // picture (from the group page at once; the marker loads later via
    // /api/part-diagram). No separate diagram blocks / «Открыть деталь» stacks,
    // and the reply is no longer held back waiting for diagrams.
    // LAXIMO_DIAGRAM_CARDS=false -> the old diagram blocks and buttons.
    const diagramCardsMode = process.env.LAXIMO_DIAGRAM_CARDS !== 'false' && laximoUsed && !serviceRequest && !compat && !workshopTopic;
    const MAX_DIAGRAM_CARDS = 8;
    const diagramCardParts = diagramCardsMode
      ? (() => { // cross-sell cards (sensor, paste) always get a place, on top of the cap
          const all = laximoNotInCatalog.map(x => laximoResult.parts.find(p => laximo.normalizeOem(p.oem) === laximo.normalizeOem(x.oem))).filter(Boolean);
          return [...all.filter(p => !p.crossSell).slice(0, MAX_DIAGRAM_CARDS), ...all.filter(p => p.crossSell).slice(0, 3)];
        })()
      : [];
    // ТО in one carousel (owner 30.10, X4 G02): every kit position is a card --
    // price-list card, or the service-unit diagram with live price -- instead of
    // a separate diagram block, «Открыть деталь» buttons and «подберёт менеджер».
    const serviceCardsMode = process.env.LAXIMO_DIAGRAM_CARDS !== 'false' && laximoUsed && serviceRequest;
    const missingLinkCodes = !diagramCardsMode && !serviceCardsMode && laximoUsed && !(compat && compat.verdict === 'fits')
      ? laximoNotInCatalog.map(x => String(x.oem || '').toUpperCase().replace(/[^A-Z0-9]/g, '')).filter(Boolean) : [];
    const allLinkCodes = [...new Set([...partLinkCodes, ...missingLinkCodes])].slice(0, 3);
    const missingWithButton = missingLinkCodes.filter(c => allLinkCodes.includes(c));
    const missingLinkNote = missingWithButton.length
      ? `\n\n═══════════════════════════════════════════\nКНОПКИ ДЛЯ НОМЕРОВ, КОТОРЫХ НЕТ В КАТАЛОГЕ ТОВАРОВ:\n═══════════════════════════════════════════\nДля номеров ${missingWithButton.join(', ')} под ответом автоматически появятся кнопки «Открыть деталь …» — они открывают страницу поиска этого номера на сайте, где видны все предложения, цены и сроки поставки. Поэтому НЕ пиши, что цену или наличие показать невозможно: скажи, что все предложения по этим номерам можно посмотреть по кнопкам ниже и там же сразу оформить заказ. Цены и сроки называй ТОЛЬКО из раздела АКТУАЛЬНЫЕ ЦЕНЫ (если он есть), другие цены НЕ придумывай; ссылки в тексте НЕ дублируй.${missingLinkCodes.length > missingWithButton.length ? ' Для остальных номеров кнопок нет — по ним предложи менеджера.' : ''}`
      : '';
    // Live price & delivery (lib/abcpPrices.js) for the numbers with a button
    // that are NOT in the feed -- same profile/warehouses as the price list.
    const feedArticles = new Set((matchedCatalog || []).map(p => String(p.article || '').toUpperCase().replace(/[^A-Z0-9]/g, '')));
    const priceNumbers = diagramCardsMode
      ? diagramCardParts.map(p => laximo.normalizeOem(p.oem))
      : allLinkCodes.filter(c => !feedArticles.has(c));
    const priceBrand = (() => { const b = String(extracted.brand || laximoResult?.vehicle?.brand || 'BMW').trim(); return /^(bmw|бмв|mini|мини)$/i.test(b) ? 'BMW' : b; })();
    let livePrices = {};
    if (priceNumbers.length && abcpPrices.enabled()) {
      progress.step('Узнаю цены и сроки доставки у поставщиков');
      try { livePrices = await abcpPrices.livePrices(priceNumbers, priceBrand, diagramCardsMode ? MAX_DIAGRAM_CARDS + 3 : 3); }
      catch (err) { console.error('[prices] failed:', err.message); }
    }
    if (Object.keys(livePrices).length) console.log('DIAG live-prices', JSON.stringify(Object.fromEntries(Object.entries(livePrices).map(([n, d]) => [n, d.cheapest
      ? { from: d.cheapest.price, days: d.cheapest.days, offers: d.count, within: d.fastCount }
      : { none_within_days: abcpPrices.MAX_DAYS, offers: d.count, fastestDays: d.fastestDays }]))));
    const diagramCardsNote = diagramCardParts.length
      ? `\n\n═══════════════════════════════════════════\nКАРТОЧКИ СО СХЕМОЙ (система добавит САМА):\n═══════════════════════════════════════════\nЭти детали тоже подходят по оригинальному каталогу и ДОСТУПНЫ для заказа — у них просто нет фото в каталоге товаров: ${diagramCardParts.map(p => `${p.oem} — ${p.name || ''}${p.axle ? ' (' + p.axle + ')' : ''}`).join('; ')}. Под ответом система сама покажет их карточками (схема BMW вместо фото, цена и срок поставки) вместе с остальными карточками. Поэтому: НЕ пиши, что их нет в каталоге, нет в наличии или что их закажет только менеджер; НЕ упоминай кнопки «Открыть деталь»; в блок <<<PRODUCTS>>> их НЕ добавляй.\nКРАТКОСТЬ: всё — номера, цены, сроки, наличие — видно в карточках. В тексте НЕ перечисляй номера деталей и цены. Текст ответа — 1–3 коротких предложения: что подобрано и для какого автомобиля, при необходимости одно короткое пояснение (например, что колодки меняют вместе с датчиком износа, или что по VIN подбор точнее).`
      : '';
    const livePriceNote = !diagramCardsMode && Object.keys(livePrices).length
      ? `\n\n═══════════════════════════════════════════\nАКТУАЛЬНЫЕ ЦЕНЫ (прямо сейчас из поиска на сайте, профиль «Опт» — цены сайта; этот раздел ВАЖНЕЕ запрета называть цену для номеров, которых нет в КАТАЛОГЕ ТОВАРОВ):\n═══════════════════════════════════════════\n${JSON.stringify(Object.fromEntries(Object.entries(livePrices).filter(([, d]) => d.cheapest)))}\nДля каждого номера: cheapest — самое дешёвое предложение (price в ₽, days — срок поставки в днях, 0 = в наличии/сегодня; daysMax — максимальный срок; noReturn — без возврата), count — сколько всего предложений. Назови цену "от <price> ₽" и срок этого предложения ("в наличии" при inStock, иначе "~N дн."). Если noReturn — предупреди, что без возврата. Скажи, что цена актуальна на сейчас, а все предложения (в том числе с более быстрым сроком) — по кнопке «Открыть деталь», где можно выбрать подходящее. НЕ добавляй эти номера в блок <<<PRODUCTS>>>. Для номеров, которых нет в этом разделе, цену НЕ называй.`
      : '';
    const partLinkNote = partLinkCodes.length
      ? `\n\n═══════════════════════════════════════════\nКНОПКА СТРАНИЦЫ ДЕТАЛИ:\n═══════════════════════════════════════════\nПод твоим ответом автоматически появится кнопка «Открыть деталь ${partLinkCodes.join(', ')}» — она открывает страницу поиска этого номера на сайте, где видны все предложения, цены и сроки поставки (в том числе позиции под заказ, которых нет в КАТАЛОГЕ ТОВАРОВ). Если товара с этим номером нет в КАТАЛОГЕ ТОВАРОВ, НЕ пиши, что по номеру "нет данных", "нет в наличии" или что его "нет в каталоге/на сайте": скажи, что цену и срок поставки можно посмотреть по кнопке ниже и там же оформить заказ${compat ? ' (совместимость — см. раздел ПРОВЕРКА СОВМЕСТИМОСТИ АРТИКУЛА)' : ''}. Саму кнопку и ссылку в тексте НЕ дублируй.\n\nНАЧАЛО ОТВЕТА (владелец, 27.10: клиенты читают только первую фразу и не открывают кнопку, если она начинается с «нет данных»): ПЕРВАЯ фраза ответа — ровно в таком виде: «По номеру ${partLinkCodes[0]} все актуальные предложения можно посмотреть по кнопке «Открыть деталь» ниже.» Номер пиши точно так, как в каталоге и на кнопке: заглавными буквами, без пробелов (${partLinkCodes.join(', ')}), а не как его набрал клиент. Никогда не начинай ответ со слов «нет данных», «нет информации», «не могу», «к сожалению», «у меня нет». Про совместимость пиши ПОСЛЕ этого, позитивно: например «Чтобы проверить, подойдёт ли деталь к вашему автомобилю, пришлите VIN или марку, модель и год».`
      : '';

    const systemWithData = SYSTEM_PROMPT
      .replace('{{CATALOG}}', catalogForPrompt)
      .replace('{{VIN_ADVICE}}', (laximoDownReason && !laximoResult) ? VIN_ADVICE_OFF : VIN_ADVICE_ON)
      .replace('{{VIN_VEHICLE}}', vinVehicleForPrompt)
      .replace('{{COMPATIBILITY}}', compatibility)
      .replace('{{LAXIMO_NOT_IN_CATALOG}}', laximoNotInCatalog.length ? JSON.stringify(laximoNotInCatalog) : '[]')
      .replace('{{OIL_PRODUCTS}}', oilProductsForPrompt) + compatNote + partLinkNote + missingLinkNote + livePriceNote + diagramCardsNote;

    // Unit diagram for a catalog part that has no product photo (fetched in
    // parallel with the AI reply; shown as a card under it). One per reply.
    let diagramPromise = null;
    let partDiagramJobs = null; // normalized OEM -> promise of its diagram (non-ТО replies)
    if (laximoUsed && process.env.LAXIMO_DIAGRAMS !== 'false') {
      const withPhoto = new Set(matchedCatalog.filter(p => p.picture).map(p => laximo.normalizeOem(p.article)));
      const first = compat && compat.verdict === 'fits'
        ? laximoResult.parts.filter(p => laximo.normalizeOem(p.oem) === laximo.normalizeOem(compat.code)) : [];
      // ТО: no diagram for a non-service part (live 26.10, X5 E70: the fallback
      // diagram showed "Крышка микрофильтра", the cabin filter COVER).
      const cand = [...first, ...laximoResult.parts].find(p => p.schema && !withPhoto.has(laximo.normalizeOem(p.oem))
        && !(serviceOnly && isNonServicePart(p.name)));
      const capped = (promise, ms) => { let t; return Promise.race([promise, new Promise(r => { t = setTimeout(() => r(null), ms); })])
        .catch(err => { console.error('[laximo] diagram failed:', err.message); return null; }).finally(() => clearTimeout(t)); };
      // A diagram for EVERY offered part without a product photo (owner, 26.10;
      // the diagram stands in for the missing card picture). Started now, in
      // parallel with the AI reply (each new part ~2 Laximo requests, 3 s apart;
      // parts of one unit share its page; everything cached 7 days); after the
      // reply the parts it actually offers are picked, one card per unit.
      if (!serviceRequest && !diagramCardsMode) {
        const seenOem = new Set();
        const cands = [...first, ...laximoResult.parts].filter(p => {
          const k = laximo.normalizeOem(p.oem);
          if (!p.schema || withPhoto.has(k) || seenOem.has(k) || (serviceOnly && isNonServicePart(p.name))) return false;
          return seenOem.add(k);
        }).slice(0, MAX_PART_DIAGRAMS);
        partDiagramJobs = new Map(cands.map(p => [laximo.normalizeOem(p.oem),
          laximo.getPartDiagram(p).catch(err => { console.error('[laximo] part diagram failed:', p.oem, err.message); return null; })]));
      }
      // ТО request: find the SERVICE unit ("ТО по регл.Oelservice / Inspektion")
      // -> full kit. Only some numbers point to it: the oil filter ELEMENT
      // (11428583898) does, the "Масляный фильтр" module (11428488578, pos. 1)
      // points to the oil filter housing unit (live test 25.10). So try the
      // likely ТО items in order (cached 7 days each) until one is the service unit.
      const serviceCands = serviceRequest ? laximoResult.parts.filter(p => p.schema && serviceCandRank(p) < 9)
        .sort((a, b) => serviceCandRank(a) - serviceCandRank(b)).slice(0, 4) : [];
      // The old route to the service unit: the "Схема" button of likely ТО
      // parts (works on the G05; on the E70 it opens the oil filter's own unit).
      // opts.stop: stop before the next Laximo request (another route already won).
      // opts.strict: return only the service unit itself (null otherwise); the
      // caller then decides on a fallback diagram.
      let schemaFallback = null; // the oil filter element's own diagram, if seen
      const viaSchemaButtons = async (opts = {}) => {
        for (const p of serviceCands) {
          if (opts.stop && opts.stop()) return null;
          const info = await capped(laximo.getPartSchemaInfo(p), 5000);   // 1 request: which unit?
          if (info && SERVICE_UNIT_RE.test(info.unitName || '')) {
            console.log(`[laximo] service unit via ${p.oem} (${p.name}): ${info.unitName}`);
            if (opts.stop && opts.stop()) return null;
            return capped(laximo.getPartDiagram(p), 6000);               // + unit page for the marker
          }
          console.log(`[laximo] ${p.oem} (${p.name}) -> unit "${info && info.unitName}", not the service unit`);
          if (!schemaFallback && info && serviceCandRank(p) === 0) schemaFallback = p;
        }
        if (opts.strict) return null;
        const fb = schemaFallback || cand;
        return fb ? capped(laximo.getPartDiagram(fb), 6000) : null;
      };
      if (serviceRequest && laximoResult.vehicleQuery) {
        // ТО (30.10): both routes to the service unit run side by side -- the car's
        // catalogue page (laximo.getServiceUnit) and the "Схема" buttons of likely
        // ТО parts -- and the first one that finds it wins; the other stops before
        // its next request. Laximo pacing is unchanged: every request still goes
        // through laximo's single queue, 3 s apart. If neither finds the unit,
        // the oil filter element's own diagram (or the first part's) is shown.
        diagramPromise = capped((async () => {
          const started = Date.now();
          let won = false;
          const stop = () => won;
          const valid = d => d && Array.isArray(d.unitParts) && d.unitParts.length > 1 && SERVICE_UNIT_RE.test(d.unitName || '') ? d : null;
          const routes = [
            ['car page', capped(laximo.getServiceUnit(laximoResult.vehicleQuery, { stop }), 20000).then(valid)],
            ['schema buttons', serviceCands.length ? viaSchemaButtons({ stop, strict: true }).then(d => d || null) : Promise.resolve(null)],
          ];
          const winner = await new Promise(resolve => {
            let left = routes.length;
            for (const [name, p] of routes) {
              p.catch(() => null).then(d => {
                if (d && !won) { won = true; resolve({ name, d }); }
                else if (--left === 0) resolve(null);
              });
            }
          });
          won = true; // stop the other route
          if (winner) {
            console.log(`[laximo] service unit found via ${winner.name} in ${Date.now() - started} ms`);
            if (winner.name !== 'car page') laximo.rememberServiceUnit(laximoResult.vehicleQuery, winner.d);
            return winner.d;
          }
          console.log(`[laximo] service unit not found by either route (${Date.now() - started} ms)`);
          const fb = schemaFallback || cand;
          return fb ? capped(laximo.getPartDiagram(fb), 6000) : null;
        })(), 22000);
      } else if (serviceCands.length) {
        diagramPromise = capped(viaSchemaButtons(), 16000);
      } else if (cand && !diagramCardsMode) {
        const job = partDiagramJobs && partDiagramJobs.get(laximo.normalizeOem(cand.oem));
        diagramPromise = capped(job || laximo.getPartDiagram(cand), 9000);
      }
    }

    // Wait for the diagram (cached: instant; new: ~2 Laximo requests, capped
    // at 9 s) so the agent knows what the card shows -- e.g. that the part
    // is discontinued (seen 25.10: 11428583898 "Не производится с 16.11.2021").
    // A copy: the result may be the cached object itself, and fields are added/removed below.
    const diagram = await (async () => { const d = diagramPromise ? await diagramPromise : null; return d ? JSON.parse(JSON.stringify(d)) : null; })();

    // Full service kit from the unit (ТО requests only): each position with the
    // feed product (if any) or the cheapest live offer, shown as a list in the
    // diagram card; the agent gets the same list.
    let serviceKitNote = '';
    let kitFeed = []; // [{part, feed}] -- kit positions that are in the price list (shown as cards)
    let kitCards = null; // serviceCardsMode: one card per kit position, in position order
    if (diagram && serviceRequest && Array.isArray(diagram.unitParts) && diagram.unitParts.length > 1
        && SERVICE_UNIT_RE.test(diagram.unitName || '')) {
      const index = await lookupCatalog(diagram.unitParts.map(p => p.oem), priceBrand).catch(() => new Map());
      const seen = new Set();
      // Max 2 variants per position (wiper sets, plug versions...), 20 rows,
      // so the last positions (fluids) aren't cut off.
      const perPos = {};
      const kitParts = diagram.unitParts.filter(p => {
        if (seen.has(p.oem)) return false;
        const k = String(p.position || '').replace(/^0+/, '');
        if ((perPos[k] = (perPos[k] || 0) + 1) > 2) return false;
        return seen.add(p.oem);
      }).slice(0, 20);
      const toPrice = kitParts.filter(p => !index.get(p.oem)).map(p => p.oem);
      let kitPrices = {};
      if (toPrice.length && abcpPrices.enabled()) {
        try { kitPrices = await abcpPrices.livePrices(toPrice, priceBrand, 20); }
        catch (err) { console.error('[prices] kit failed:', err.message); }
      }
      kitFeed = kitParts.map(p => ({ part: p, feed: index.get(p.oem) })).filter(x => x.feed);
      diagram.kit = kitParts.map(p => {
        const feed = index.get(p.oem);
        const lp = kitPrices[p.oem];
        const discontinued = Object.entries(p.notes || {}).some(([k, v]) => /не производ|снят/i.test(`${k} ${v}`));
        return {
          position: p.position, oem: p.oem, name: p.name, qty: p.qty, discontinued,
          ...(feed ? { inFeed: true, price: Number(feed.price) || null, url: feed.url || null, stock: feed.stock } : {}),
          ...(!feed && lp && lp.cheapest ? { priceFrom: lp.cheapest.price, days: lp.cheapest.days, inStock: lp.cheapest.inStock, noReturn: lp.cheapest.noReturn, offers: lp.count } : {}),
        };
      });
      // Per POSITION (owner, 25.10): "discontinued" only when the catalog says
      // so for every variant of the position; positions merely missing from the
      // price list are "orderable via the manager" (live 25.10 the bot called
      // brake fluid, coolant and washer fluid "сняты с производства" because the
      // prompt used one sentence for both cases). A position with any variant
      // in the feed is covered by its card.
      const kitFacts = serviceCardsMode ? serviceKitCardFacts(diagram.kit) : serviceKitFacts(diagram.kit);
      diagram.kitFacts = kitFacts;
      if (serviceCardsMode) {
        const v = laximoResult?.vehicle || {};
        const label = `${v.brand || 'BMW'} ${v.name || ''}`.trim();
        kitCards = buildKitCards(kitParts, index, kitPrices, diagram, label);
      }
      console.log('DIAG service-kit', JSON.stringify({ unit: diagram.unitName, items: diagram.kit.length, inFeed: diagram.kit.filter(k => k.inFeed).length, priced: diagram.kit.filter(k => k.priceFrom).length, positions: kitFacts.positions ? { all: kitFacts.positions.length, discontinued: kitFacts.discontinued.length, asNeeded: kitFacts.asNeeded.length } : { inCards: kitFacts.inCards.length, orderViaManager: kitFacts.orderViaManager.length, discontinued: kitFacts.discontinued.length } }));
      if (serviceCardsMode) serviceKitNote = `\n\n═══════════════════════════════════════════\nПОЛНЫЙ СОСТАВ ТО ПО ОРИГИНАЛЬНОМУ КАТАЛОГУ (узел «${diagram.unitName}» для этого автомобиля):\n═══════════════════════════════════════════\n${JSON.stringify(diagram.kit)}\nКлиент спрашивает про ТО. Под ответом система САМА покажет КАРТОЧКИ ВСЕХ позиций ТО одной лентой (фото или схема BMW, цена, срок) — в блок <<<PRODUCTS>>> их НЕ добавляй, кнопок «Открыть деталь» и отдельной схемы нет. Ответ КОРОТКИЙ: одна строка-вступление с автомобилем; одна строка с перечнем позиций БЕЗ номеров и цен; затем по разделу «ИТОГ» ниже: если discontinued не пуст — одно предложение, что эти позиции BMW сняла с производства, но они ещё есть у поставщиков (цена и срок в карточке), а менеджер подскажет новый номер; если asNeeded не пуст — одно предложение, что эти позиции по каталогу меняются по необходимости, а не на каждом ТО; затем вопрос про моторное масло и колодки/диски. НЕ пиши, что какие-то позиции «подберёт/закажет менеджер» или что их нет на сайте. Номера, цены и сроки в текст НЕ пиши. Пробег и интервалы НЕ спрашивай.\n\nИТОГ ПО ПОЗИЦИЯМ ТО (используй ТОЛЬКО эти факты): ${JSON.stringify(diagram.kitFacts)}`;
      else serviceKitNote = `\n\n═══════════════════════════════════════════\nПОЛНЫЙ СОСТАВ ТО ПО ОРИГИНАЛЬНОМУ КАТАЛОГУ (узел «${diagram.unitName}» для этого автомобиля):\n═══════════════════════════════════════════\n${JSON.stringify(diagram.kit)}\nКлиент спрашивает про ТО. Под ответом будет схема узла (с отмеченной позицией) и карточки позиций, которые есть на сайте. Ответ КОРОТКИЙ (см. СТАНДАРТНОЕ ТО): одна строка-вступление, одна строка с перечнем позиций БЕЗ номеров и цен, затем по разделу «ИТОГ ПО ПОЗИЦИЯМ ТО» ниже: если список orderViaManager не пуст — одно предложение, что эти позиции подберёт и закажет менеджер (НЕ называй их снятыми с производства и НЕ говори, что их нет в каталоге/на сайте); если список discontinued не пуст — одно предложение, что эти позиции сняты с производства и менеджер подберёт актуальную замену; затем вопрос про моторное масло и колодки/диски. Слова «снят(ы) с производства» — ТОЛЬКО для позиций из списка discontinued. Номера, цены и сроки по позициям в текст НЕ переписывай — они в карточках. Пробег и интервалы НЕ спрашивай. Это правило ВАЖНЕЕ разделов «АКТУАЛЬНЫЕ ЦЕНЫ» и «КНОПКИ…»: для ответа на ТО цены и сроки отдельных номеров в тексте НЕ называй. Все позиции с inFeed=true система САМА добавит карточками (до 12 карточек) — в блок <<<PRODUCTS>>> их можно не включать.\n\nИТОГ ПО ПОЗИЦИЯМ ТО (готовые факты по позициям узла, используй ТОЛЬКО их): ${JSON.stringify(diagram.kitFacts)}\n- inCards: позиции, которые будут в карточках;\n- orderViaManager: позиций нет в карточках, но их можно заказать — подберёт и закажет менеджер;\n- discontinued: позиции, все номера которых по каталогу сняты с производства.`;
    }
    // Extra diagrams (owner, 25.10): an "Открыть деталь" number that is NOT on
    // the main diagram gets its own card with its position marked -- max 2
    // (each costs ~2 Laximo requests; cached 7 days), capped at 9 s together.
    let extraDiagrams = [];
    if (!diagramCardsMode && laximoUsed && laximoResult && process.env.LAXIMO_DIAGRAMS !== 'false' && allLinkCodes.length && !partDiagramJobs) {
      const onMain = new Set([...(diagram && Array.isArray(diagram.unitParts) ? diagram.unitParts.map(p => laximo.normalizeOem(p.oem)) : []),
        ...(diagram ? [laximo.normalizeOem(diagram.oem)] : [])]);
      const extraParts = allLinkCodes.filter(c => !onMain.has(laximo.normalizeOem(c)))
        .map(c => laximoResult.parts.find(p => p.schema && laximo.normalizeOem(p.oem) === laximo.normalizeOem(c)))
        .filter(Boolean).slice(0, 2);
      if (extraParts.length) {
        let t;
        const all = Promise.all(extraParts.map(p => laximo.getPartDiagram(p).catch(err => { console.error('[laximo] extra diagram failed:', err.message); return null; })));
        extraDiagrams = ((await Promise.race([all, new Promise(r => { t = setTimeout(() => r([]), 9000); })]).finally(() => clearTimeout(t))) || [])
          .filter(d => d && d.image && (!diagram || d.image !== diagram.image)); // same unit -> no second card
        for (const d of extraDiagrams) { delete d.unitParts; delete d.kit; }
        console.log(`DIAG extra-diagrams ${extraParts.map(p => p.oem).join(',')} -> ${extraDiagrams.length}`);
      }
    }
    if (diagram) delete diagram.unitParts; // the card gets `kit` instead

    const workshopNote = workshopTopic
      ? `\n\n═══════════════════════════════════════════\nТЕМА — УСЛУГА СЕРВИСА (${workshopTopic === 'keys' ? 'изготовление ключей' : 'кодирование / чип-тюнинг / прошивка'}):\n═══════════════════════════════════════════\nКлиент спрашивает про услугу BMW-сервиса, а не про запчасть. Отвечай по навыку «${workshopTopic === 'keys' ? 'ИЗГОТОВЛЕНИЕ КЛЮЧЕЙ BMW и MINI' : 'КОДИРОВАНИЕ, ЧИП-ТЮНИНГ, ПРОШИВКА'}». НЕ подбирай детали, НЕ добавляй блоки <<<PRODUCTS>>> и кнопки подбора запчастей; кнопки — только про запись/связь (например «📞 Записаться», «Связаться с менеджером»). Модификацию двигателя для этой услуги не уточняй.`
      : '';
    const morePartDiagramsNote = partDiagramJobs && partDiagramJobs.size > 1
      ? `\nДля остальных предлагаемых номеров без фото система тоже покажет схемы узлов (по одной на узел, позиции отмечены красным) — перечислять их отдельно не нужно; каждый номер, который ты предлагаешь, пиши полностью (11 цифр), чтобы к нему добавилась схема.`
      : '';
    const diagramNote = diagram
      ? `\n\n═══════════════════════════════════════════\nСХЕМА ПОД ОТВЕТОМ:\n═══════════════════════════════════════════\nПод твоим ответом будет показана схема узла «${diagram.unitName || ''}» с отмеченной позицией ${diagram.position || ''}: ${diagram.oem} — ${diagram.name || ''}${diagram.qty ? ` (${diagram.qty})` : ''}.${diagram.notes && Object.keys(diagram.notes).length ? ` Примечания каталога: ${Object.entries(diagram.notes).map(([k, v]) => `${k}: ${v}`).join('; ')}.` : ''} Можешь коротко сослаться на схему ("позиция ${diagram.position || ''} на схеме ниже"). Если в примечаниях сказано, что деталь не производится — ОБЯЗАТЕЛЬНО скажи (одним коротким предложением), что этот номер снят с производства, и что менеджер подскажет актуальную замену. Описывай деталь по её названию из каталога (например, сменный элемент фильтра — это не «вариант к корпусу»).`
      : '';
    const extraDiagramNote = extraDiagrams.length
      ? `\nТакже под ответом будут схемы для: ${extraDiagrams.map(d => `${d.oem} — ${d.name || ''} (узел «${d.unitName || ''}», позиция ${d.position || ''}${d.notes && Object.keys(d.notes).length ? `; примечания: ${Object.entries(d.notes).map(([k, v]) => `${k}: ${v}`).join('; ')}` : ''})`).join('; ')}. Если номер снят с производства — скажи об этом одним коротким предложением.`
      : '';

    progress.step('Пишу ответ…');
    const answerStarted = Date.now();
    const claudeRes = await llmFetch({
        model:       LLM_MODEL,      // env LLM_MODEL (default deepseek-v4-pro).
                                         // Sonnet 5 REJECTS non-default
                                         // temperature/top_p/top_k with a 400 error, so temperature
                                         // is intentionally omitted here (was 0.2 for Haiku).
        max_tokens:  16000, // 25.10: 4096 cut a ТО answer off inside <<<PRODUCTS>>> again.
                            // Sonnet 5 THINKS BY DEFAULT (adaptive, effort high) and the
                            // thinking counts toward max_tokens, so a long answer plus its
                            // thinking didn't fit. Only tokens actually used are billed.
                            // History: was 2048 -- too tight for a full TO service kit
                           // (5+ verbose product entries with long URLs/
                           // picture links + intro prose sharing the same
                           // budget), causing the response to cut off
                           // mid-JSON. The widget can't parse a truncated
                           // <<<PRODUCTS>>> block, so it silently fell back
                           // to showing the raw (broken) text instead of
                           // rendering cards.
        system:      systemWithData + diagramNote + extraDiagramNote + morePartDiagramsNote + serviceKitNote + workshopNote,
        messages:    messages,
      }, 120000, ANSWER_THINKING_OFF);

    if (!claudeRes.ok) {
      const err = await claudeRes.text();
      console.error(`${isAccountError(claudeRes.status) ? '[llm] ACCOUNT/KEY PROBLEM -- check LLM_API_KEY, balance and account status. ' : ''}LLM API error (${LLM_MODEL}, HTTP ${claudeRes.status}):`, err);
      Object.entries(headers).forEach(([k, v]) => res.setHeader(k, v));
      return res.status(502).json({ error: 'Upstream API error', detail: err });
    }

    const data = await claudeRes.json();
    trackUsage(LLM_MODEL, data);
    console.log(`[answer] ${LLM_MODEL}: ${Date.now() - answerStarted} ms, out ${data.usage?.output_tokens ?? '?'} tokens, thinking ${ANSWER_THINKING_OFF && thinkingOffSupported ? 'off' : 'on'}`);
    // Find the actual text block by TYPE, not by array position. Sonnet 5
    // (and any model with thinking/adaptive-thinking enabled) can return a
    // {type: "thinking", ...} block BEFORE the text block, so content[0]
    // is not reliably the reply -- that was silently returning an empty
    // string here (tokens billed, nothing rendered) once we switched off
    // Haiku, which never produced thinking blocks so this bug was latent.
    const textBlock = (data.content || []).find(block => block.type === 'text');
    let text = textBlock?.text ?? '';
    // History placeholders the widget writes for shown cards/diagrams (live 30.10:
    // DeepSeek copied «[запчасти показаны]» into its reply although no cards came).
    text = stripHistoryPlaceholders(text);
    if (data.stop_reason === 'max_tokens') {
      console.warn(`[chat] reply hit max_tokens (output ${data.usage?.output_tokens ?? '?'} tokens)`);
    }
    text = repairTruncatedBlocks(text);
    // A discontinued part never goes out as a plain card (owner 30.10): the card's
    // line says so whenever the catalog notes for that number say «Не производится».
    if (diagramCardParts.length) {
      const v = laximoResult.vehicle || {};
      const carLabel = `${v.brand || 'BMW'} ${v.name || ''}${v.options?.['Код модели'] ? ' (' + v.options['Код модели'] + ')' : ''}`.trim();
      text = mergeDiagramCards(text, labelSameNameCards(diagramCardParts, diagramCardParts.map(p => diagramCardFor(p, livePrices[laximo.normalizeOem(p.oem)], carLabel))));
      console.log(`[chat] diagram cards: ${diagramCardParts.map(p => p.oem + (livePrices[laximo.normalizeOem(p.oem)] ? ' (price)' : ' (no offers)')).join(', ')}`);
    }
    text = markDiscontinuedCards(text, [...(laximoResult?.parts || []), ...(diagram ? [diagram] : []), ...extraDiagrams]);
    text = labelVariantCards(text, laximoResult?.parts || []);
    if (diagramCardsMode) {
      const v = laximoResult.vehicle || {};
      text = ensureCardPerKeyword(text, {
        keywords: extracted.partKeywords,
        parts: laximoResult?.parts || [],
        feedByOem: new Map((matchedCatalogByVehicle || []).map(p => [String(p.article || '').toUpperCase().replace(/[^A-Z0-9]/g, ''), p])),
        carLabel: `${v.brand || 'BMW'} ${v.name || ''}${v.options?.['Код модели'] ? ' (' + v.options['Код модели'] + ')' : ''}`.trim(),
      });
      text = sortCardsByAxle(text, laximoResult?.parts || []);
      if (/<<<PRODUCTS>>>/.test(text)) {
        const v = laximoResult.vehicle || {};
        text = cleanCardsText(text, `Подобрал детали по оригинальному каталогу BMW для вашего ${v.brand || 'BMW'} ${v.name || ''} — всё в карточках ниже.`.replace(/\s+/g, ' '));
      }
    }
    // A part number with an "Открыть деталь" button: never open the answer with
    // "нет данных" (owner, 27.10 -- customers stop reading and don't open the
    // button). Safety net for the prompt rule in partLinkNote.
    if (allLinkCodes.length) text = positiveFirstSentence(text, allLinkCodes);
    // Found part = self-service purchase (owner, 28.10): no manager button
    // unless the customer asked for a person or the check did not confirm the part.
    text = dropNeedlessManagerButton(text, {
      partFound: allLinkCodes.length > 0 || diagramCardParts.length > 0 || /<<<PRODUCTS>>>/.test(text),
      lastUserText: (([...(messages || [])].reverse().find(m => m.role === 'user')) || {}).content,
      compatVerdict: compat ? compat.verdict : null,
    });
    // «Менеджер уточнит сроки поставки» under cards (owner 06.11: seen often): the
    // card and the product page already show price, stock and delivery times.
    if (/<<<PRODUCTS>>>/.test(text) || allLinkCodes.length || diagramCardParts.length) text = dropManagerDetailsLine(text);

    // The customer typed a phone/email into the chat: the LLM saw only a mask.
    // Open the request form (the widget fills it from the customer's own
    // message, in the browser) so the contact reaches the manager through our
    // database only, with the customer's consent. Not when the contact was
    // given to check an order -- that path is answered above.
    if (typedContacts.inLast && !extracted.orderNumber) {
      if (!text.includes('<<<MANAGER_BUTTON>>>')) text = `${text}\n<<<MANAGER_BUTTON>>>`;
      text = `${text}\n<<<CONTACT_FORM>>>`;
    }
    // ТО kit: every kit position that is in the price list becomes a card
    // (the AI tends to pick only what its keywords matched -- live test
    // Follow-up about ONE kit position (Диалоги 05.11: «Сколько свечи нужно заказать?»
    // after the ТО answer -> all 10 ТО cards again): only that position's cards.
    const kitItem = kitItemAsked(lastUserMessage(messages));
    if (kitItem) {
      const fits = c => kitItem.test(`${(c.part && c.part.name) || ''} ${(c.feed && c.feed.name) || ''} ${c.name || ''}`);
      const kc = (kitCards || []).filter(fits), kf = kitFeed.filter(fits);
      if (kc.length || kf.length) {
        console.log(`[chat] ТО follow-up about one position (${kitItem}): ${kc.length || kf.length} card(s) instead of the whole kit`);
        if (kitCards) kitCards = kc;
        kitFeed = kf;
      }
    }
    // 25.10 showed 3 cards for a ~10-item service set). Max 12 cards.
    if (kitCards && kitCards.length) {
      text = mergeServiceCards(text, kitCards);
      // Every position is a card with a price (or the manager is named on the card
      // itself): «… подберёт / закажет менеджер» sentences are wrong here (live 30.10).
      const MGR_RE = /(подбер|закаж|уточн)\S*[^.!?\n]{0,30}менеджер|менеджер[^.!?\n]{0,30}(подбер|закаж)/i;
      text = text.replace(/^[^<]*/, prose => prose.split('\n').map(line => line.split(/(?<=[.!?…])\s+/).filter(x => !MGR_RE.test(x)).join(' ')).join('\n').replace(/\n{3,}/g, '\n\n'));
      const v = laximoResult?.vehicle || {};
      text = cleanCardsText(text, `Подобрал набор ТО по оригинальному каталогу BMW для вашего ${v.brand || 'BMW'} ${v.name || ''} — всё в карточках ниже.`.replace(/\s+/g, ' '));
    } else if (kitFeed.length) text = mergeKitCards(text, kitFeed, laximoResult?.vehicle?.name || [extracted.brand, extracted.model].filter(Boolean).join(' '));
    // ТО: no housings, covers, seals... among the cards (kit positions always stay).
    if (serviceOnly) text = dropNonServiceCards(text, new Set([...kitFeed.map(x => String(x.feed.article || '').toUpperCase().replace(/[^A-Z0-9]/g, '')), ...(kitCards || []).map(c => String(c.article || '').toUpperCase().replace(/[^A-Z0-9]/g, ''))]));
    // The diagram card describes only the part marked in red (owner, 25.10):
    // the kit list is used for the cards and the prompt, not shown in the card.
    if (diagram) { delete diagram.kit; delete diagram.kitFacts; }
    // Diagrams for every part the reply offers (non-ТО, see partDiagramJobs):
    // numbers written in the reply or with an "Открыть деталь" button. Waits at
    // most PART_DIAGRAMS_WAIT_MS more (the jobs ran during the AI call; the
    // ones still running keep filling the cache for next time). Same unit ->
    // one card with several marked positions (`marks`).
    let diagramCards = diagram ? [diagram] : [];
    if (partDiagramJobs && partDiagramJobs.size) {
      const offered = offeredCodes(text, [...partDiagramJobs.keys()], allLinkCodes.map(c => laximo.normalizeOem(c)));
      let t;
      const got = await Promise.race([Promise.all(offered.map(k => partDiagramJobs.get(k))),
        new Promise(r => { t = setTimeout(() => r(null), PART_DIAGRAMS_WAIT_MS); })]).finally(() => clearTimeout(t));
      const ready = got || await Promise.all(offered.map(k => Promise.race([partDiagramJobs.get(k), Promise.resolve(null)])));
      diagramCards = groupPartDiagrams(diagramCards, ready);
      // the first part's diagram (prepared for the prompt) only if the reply offers it
      if (diagram && offered.length && !offered.includes(laximo.normalizeOem(diagram.oem))
          && !(diagram.marks || []).some(m => offered.includes(laximo.normalizeOem(m.oem)))) {
        diagramCards = diagramCards.filter(c => c !== diagram);
      }
      diagramCards = orderCardsByText(diagramCards, text).slice(0, MAX_PART_DIAGRAMS); // same order as the reply text (owner 28.10)
      extraDiagrams = diagramCards.filter(c => c !== diagram);
      console.log(`DIAG part-diagrams offered=${offered.length} ready=${ready.filter(Boolean).length}${got ? '' : ' (wait cut)'} cards=${diagramCards.length} marks=${diagramCards.reduce((n, c) => n + (c.marks ? c.marks.length : 1), 0)}`);
    }
    // Button under each diagram (owner, 26.10): the marked part's product page
    // when it's in the price list; the widget falls back to the site search.
    {
      const urlByCode = new Map();
      for (const p of matchedCatalog || []) if (p && p.url) urlByCode.set(laximo.normalizeOem(p.article), p.url);
      for (const x of kitFeed || []) if (x.feed && x.feed.url) urlByCode.set(laximo.normalizeOem(x.feed.article), x.feed.url);
      const allMarks = [diagram, ...extraDiagrams].filter(Boolean).flatMap(d => d.marks || [d]);
      const missing = allMarks.filter(d => d && d.oem && !urlByCode.has(laximo.normalizeOem(d.oem))).map(d => d.oem);
      if (missing.length) {
        const more = await lookupCatalog(missing, priceBrand).catch(() => new Map());
        for (const [code, p] of more) if (p && p.url) urlByCode.set(code, p.url);
      }
      for (const d of [diagram, ...extraDiagrams, ...allMarks]) {
        const u = d && d.oem ? urlByCode.get(laximo.normalizeOem(d.oem)) : null;
        if (u) d.productUrl = u;
      }
    }
    const finalCards = kitCards && kitCards.length ? [] : partDiagramJobs ? diagramCards : [diagram, ...extraDiagrams].filter(Boolean);
    for (const d of finalCards) {
      console.log('DIAG diagram', JSON.stringify({ oem: d.oem, unit: d.unitName, position: d.position, box: !!d.box, marks: d.marks ? d.marks.length : 1 }));
      text = `${text}\n<<<DIAGRAM>>>\n${JSON.stringify(d)}\n<<<END_DIAGRAM>>>`;
    }
    if (allLinkCodes.length) {
      text = `${text}\n<<<PART_LINKS>>>\n${JSON.stringify(allLinkCodes)}\n<<<END_PART_LINKS>>>`;
    }

    Object.entries(headers).forEach(([k, v]) => res.setHeader(k, v));
    res.setHeader('Content-Type', 'application/json');
    return res.status(200).json({ reply: text, ...(catalogOutcome ? { catalog: catalogOutcome } : {}) });

  } catch (err) {
    console.error('Handler error:', err);
    Object.entries(headers).forEach(([k, v]) => res.setHeader(k, v));
    return res.status(500).json({ error: err.message });
  }
}

// Exported as a plain function (unchanged from before, so
// `require('./api/chat.js')` and however server.js mounts it keeps working
// exactly as-is) with clearCaches attached as a property -- functions are
// objects in JS, so this is safe and doesn't change the default export's
// shape or behavior at all.
module.exports = handler;
